INSERT INTO `tbl_branch` (`id`, `branch_village`, `branch_name`, `mahant_name`, `mahant_mobile`, `details`, `photo`, `created_at`) VALUES
(10, 'શાહપુર (રાજસ્થાન)', 'રામસ્નેહિ શાખા', 'ગોવિંદરામશાસ્ત્રી', '0000000000', 'શ્રી રામાનંદ આચાર્ય ની પરંપરા માં રાજસ્થાન માં સંતો ના ૪ સંપ્રદાયો મુખ્યત્વે વિકાસ પામ્યા હતા. (૧) દાદુ પંથી (૨) નિરંજની (૩) રામસ્નેહિ – શાહપુર શાખા (૪) રામસ્નેહિ – સિંહલ શાખા.\r\nઆમાં દાદુપંથી કબીરજી ના પુત્ર કમાલ ના શિષ્ય દાદુ થી વીસ્તાર પામી હતી. નીરંજન શાખા ના પ્રવર્તક સંત હરીદાસજી સોળમી સદી ના મધ્ય થી સત્તરમી સદીના મધ્ય સુધી ના સમયમાં થયેલ, જેમની મુખ્ય શાખા જોધપુર માં છે.\r\nરામસ્નેહી શાખા શાહ્પુર ના પ્રવર્તક શ્રી રામચણદાસજી નો જન્મ સવંત ૧૭૭૬ અને નીર્વાણ ૧૮૫૫ ની સાલ માં થયેલ તેમના ૨૨૫ જેટલા સમર્થ શીષ્યો હતા. વૈષ્ણવાચાર્ય શ્રી રામક્રુષ્ણ્દાસજી પાસેથી તેમણે વૈષ્ણવી દીક્ષા  લિધી હતી. સવંત ૧૮૦૮ માં એક ગુફા માં પચીસ વર્ષ સુધી તપ- ભજન કરેલ અને તપ માં થી બહાર આવ્યા ત્યારે શાહપુર નરેશ તેમને શાહપુર તેડી ગયા અને ત્યાં સ્થાન બંધ્યુ અને રામસ્નેહિ સંપ્રદાય ની સ્થાપના કરી.\r\nરામસ્નેહિ શાખા સિંથલ નાં મુખ્ય પ્રવર્તક સંત શ્રી હરિરમજી બીકાનેર બાજુમાં સિંહથલ ગામે થયા વૈષ્ણ્વાચર્ય શ્રી જૈમલદાસજી પાસેથી વૈષ્ણવી દીક્ષા સવંત ૧૭૦૦ માં લીધી અને ૧૮૩૫ માં નેર્વાણ પામ્યા. તેમણે રામસ્નેહિ સંપ્રદાય ની બીજી શાખા સિંહથલ માં સ્થાપી.\r\nઉપરોક્ત બંને રામસ્નેહિ શાખાના અત્યારે ગુજરાત, રાજસ્થાન, અને મધ્યપ્રદેશ માં ઘણાં સ્થાન આવેલાં છે.રામસ્નેહિ સંપ્રદાય ની બન્ને શખાઓ ના સંતો રામસ્નેહિ શાખા થી ઓળખાય છે. તેઓ રામસ્નેહિ સંપ્રદાય ના રામાવત વૈષ્ણ્વ છે.', '1765287402_1001160626.jpg', '2025-12-09 19:06:42'),
(11, 'દડવા', 'વાઘાણી શાખા', 'અભિનીત બાપુ', '95585 49380', 'શ્રી કુબાજી સંતની પરંપરા મા શ્રી કુબાજી ના શીષ્ય ગોપાલદાસજી, તેમના શીષ્ય શામદાસજી, તેમના શીષ્ય હિરદાસજી, તેમના શીષ્ય ચેતનદાસજી મહારાજ ના ત્રણ મુખ્ય શિષ્યો  (૧) શ્રી દેશળજી (૨) શ્રી આશરામજી (૩) શ્રી વાઘારામજી તે ત્રણે સંતો શાખા પ્રવર્તક થયા.\r\nશ્રી કુબાજી સંતની પરંપરા માં શ્રી ચેતનદાસજી મહારાજ ના ત્રીજા સંત શ્રી વાઘારામજી મહારાજે દડવા ગામે ગાદી સ્થાપી અને તેમની પરંપરા ના સંતો ત્યારથી વાઘાણી શાખાથી ઓળખાય છે. દેશાણી, આશાણી, વાઘાણી આ સહુ સંતો કુબાવત દ્વાર ના છે અને રામવત વૈષ્ણવ છે.', '1765290394_1001160666.jpg', '2025-12-09 19:56:34'),
(12, 'ચુલી .તાલુકો. ધ્રાંગધ્રા. જિલ્લો. સુરેન્દ્રનગર', 'ચાંપબાઈ શાખા', 'પ્રભુદાસજી મોહનદાસજી ચાંપબાઈ', '0000000000', 'શ્રી ગુરુ રામાનંદ સ્વામીના સમર્થ શિષ્યઓ માં શ્રી કબીરજી ના એક શિષ્ય શ્રી પદ્મનાભજી હતા. શ્રી પદ્મનાભજી ના એક શિષ્ય શ્રી નિલકંઠ સ્વામી, તેમન શિષ્ય શ્રી રૂગનાથજી, તેમન શિષ્ય શ્રીયાદવદસજી અને તેમના શિષ્ય શ્રી ષટ્પ્રજ્ઞસ્વામિજી. તેમનો જન્મ સવંત ૧૬૬૮ માં થયેલો.\r\nએક માહિતી પ્રમાણે મહારાજા શ્રી યોગરાજસિંહ ને પાંચ પુત્રો હતા અને એક પુત્રી હતી પુત્રી નું નામ ચંપાબા હતું પાંચ પુત્રો નાં નામ હતા સામંતસિંહ, અમરસિંહ, અજયસિંહ, મંગળજી અને મેળાજી. તેમાં સામંતસિંહજી એ રામમંત્ર ની દિક્ષા લીધી અને તે  ષટપ્રજ્ઞસ્વામી તરીકે ઓળખાયા. અને તેમના બહેન ચંપાબા ચાંપબાઈ તરીકે ઓળખાયા.શ્રી ષટ્પ્રજ્ઞસ્વામિજી ના બહેન શ્રી ચાંપબાઇ બહેન મહાન રામભક્ત હતા. સહુ સંતો ની શુભેચ્છા થી તેમણે ચુલી ગામે આશ્રમ સ્થાપ્યો. તેમની શિષ્ય પરંપરા ના સંતો ત્યારથી ચાંપબાઇ બહેન ની શાખા થી ઓળખય છે. તેઓ પદ્મનાભ દ્વારાના છે અને (રામ કબીર) રામવત વૈશ્ણ્વ છે.\r\nબીજી એક માહિતી પ્રમાણે શ્રી ષટપ્રજ્ઞસ્વામીજી ફરતા ફરતા ચુલી ગામે આવ્યાં ત્યા ચંપાબાઈ નામે એક ક્ષત્રીયાણી રહેતા હતા. તેઓ સ્વામીજી ના દર્શને આવ્યા અને સ્વામીજી ને વીનંતી કરી કે મને રામ મંત્ર ની દીક્ષા આપો.આમ ચંપાબાઈ એ ચુલી મા આશ્રમ સ્થાપ્યો અને તેમના શીષ્યો ચાંપબાઈ સાધુ તરીકે ઓળખાયા. ચુલી ગામ ધ્રાંગધ્રા-હળવદ હાઈવે પર આવેલું છે.', '1765290745_1001160673.jpg', '2025-12-09 20:02:25'),
(13, 'બરોલ.તાલુકો.લીંબડી. જિલ્લો. સુરેન્દ્રનગર', 'બરોલીયા', 'રમેશબાપુ', '0000000000', 'શ્રી ગુરુ રામાનંદ સ્વામી ની પરંપરામાં અનંતાનંદજી ના શિષ્ય ક્રુષ્ણદાસજી પયહારી ગલતા ગાદી જયપુરમાં થયા. તેમનાં મુખ્ય ૨૪ શિષ્યો માં  મુખ્ય કિલ્હદાસજી ની  પરંપરામાં  જોગવાનજી સંત દ્વારા પ્રવર્તક થયા. જેથી જોગવાનજી  શિષ્ય પરંપરા ત્યારથી  જોગવાનજી દ્વારા થી ઓળખાય છે. જોગવાનજી મહારાજ ની પરંપરા માં તુલસીદાસજી– ->તેમના શિષ્ય રામકુબેરદાસજી —>તેમના શિષ્ય રામમનોહરદાસજી —>તેમના શિષ્ય શ્યામદાસજી —>તેમના શિષ્ય દયળદાસજી —>અને તેમના શિષ્ય રામદાસજી (શ્યામદાસજી) મહારાજે સૌરાષ્ટ્ર યાત્રા વખતે લીંબડી બાજુનાં બરોલ ગામે ગાદી સ્થપી અને તેમની પરંપરા નાં સંતો ત્યારથી બરોલીયા શાખાથી ઓળખાય છે. તેઓ જોગનજી દ્વારાનાં છે. અને વૈષ્ણવ છે.', '1765291026_1001160682.jpg', '2025-12-09 20:07:06'),
(14, 'કમીજળા', 'રવિભાણ', 'વર્તમાન મહંત ની માહિતી હોય તો મોકલવા વિનંતી', '0000000000', 'સુરેન્દ્રનગર જીલ્લા ના વરાહી ગામ માં એક લોહાણા સજ્જન રહેતા હતાં. તેમનું નામ ભાણા ભગત હતું. તેમને શ્રી ષટ્પ્રજ્ઞસ્વામીજી ની કીર્તી ની વાત સાંભળી ને તેમને મળવા નું મન થયું. તેઓ એક દીવસ ફરતા ફરતા દુધરેજ આવ્યા અને ષટ્પ્રજ્ઞસ્વામીજી ને સંદેશ મોક્લ્યો કે વારહી ગામ થી ભાણા ભગત આપના દર્શન કરવા આપને મળવા ની આજ્ઞા માંગે છે. પરંતુ સ્વામીજી એ આજ્ઞા ના આપી તેથી ભાણા ભગત દુધરેજ ના સરોવર કિનારે જઈ ભગવાન ની ભક્તિ કરવા બેસી ગયા. ત્રણ દિવસ વિતતા શ્રી ષટ્પ્રજ્ઞસ્વામીજી ને ભગવાને સ્વપ્નમાં આવી કહ્યુ કે “વારાહી થી આવેલા ભણા ભગત ને આશ્રમ માં બોલાવો” સવારે સ્વામીજી એ પોતાનાં શિષ્યને ભાણાભગત ને તેડવા મોકલ્યા. આમ મંડળી સહીત ભણાભગત આશ્રમ માં પધાર્યા. સત્સંગ થયો અને સ્વામીજી એ ભાણા ભગત ને રામ મંત્ર ની દિક્ષા આપી અને કહ્યું કે તમારી શિષ્યપરંપરા ”સાહેબ” તરીકે ઓળખાશે. આમ ભાણાભગત ભાણ સાહેબ તરીકે ઓળખાયા.\r\nશ્રી રામાનંદજી, શ્રી કબીરજી, શ્રી પદ્મ્નાભજી, શ્રી ષટ્પ્રજ્ઞ સ્વામિ દ્વારા શ્રી ભાણદાસજી સાહેબ ને મંત્ર ઉપદેશ મળેલો અને આધ્ય રામકબીર સંપ્રદાય નો સિધ્ધંત આપી ને “સાહેબ” એવા નામ થી બોલાવ્યા અને કહ્યુ કે તમે પરમાત્મા પાસેથી ક્રુપા મેળવી છે. આજથી તમે સહેબ કહેવાશો અને તમારી પરંપરા સાહેબ થી ઓળખાશે.\r\nશ્રી ષટ્પ્રજ્ઞ સ્વામિ પાસેથી પરંપરા લઇ ને શ્રી ભાણદાસજી સાહેબે ગામ વરાહિ માં ગાદી સ્થાપી. તેમની તેમના પુત્ર ખીમ સાહેબ અને રવિ સાહેબ એમ બે પરંપરા શરુ થઇ. પરંતુ શ્રી રવિ સહેબ સમર્થ સંત હતા, જેથી શ્રી ખીમ સાહેબ તેમના શીષ્ય બની ગયા. આ સંપ્રદાય માં ભાણ સાહેબ પછી રવી સાહેબે રાપર (કચ્છ) વિગેરે સ્થળો એ સંસ્થા બાંધી છે. શ્રી મોરાર સાહેબ વિગેરે સંતો દ્વારા આ સંપ્રદાય ખુબ વિકાસ પામ્યો છે. વરહિ – શેરખી – ખંભાળીયા – કમીજડા – વડોદરા – રાપર – વાંકાનેર વગેરે સ્થળો આ પરંપરા નાં સંતો ત્યારથી રવીભણ શાખાથી ઓળખાય છે. તેઓ ભાણસહેબ દ્વારાનાં (રામકબીર) રામાવત વૈષ્ણવ છે.', '1765291542_1001160691.jpg', '2025-12-09 20:15:42'),
(15, 'રંગપુર. તાલુકો. ધંધુકા.જિલ્લો.અમદાવાદ', 'રામદેવપુત્રા', 'મહંત નામ ની માહિતી કોઇ પાસે હોય તો મોકલવા વિનંતી', '0000000000', 'રામદેવપુત્રા શાખા નું મુળસ્થાન રાજસ્થાન માં આવેલું છે. જેમને ભગવાન નો અવતાર માનવામાં આવે છે તેઓ શ્રી રામદેવજી મહારાજ ની ભક્તિ પરંપરા માં શ્રી શ્યામદાસજી મહારાજ મહા સમર્થ સંત થઇ ગયા. ભક્તિ પ્રચાર અને તિર્થયાત્રા માટે તેઓ સૌરાષ્ટ્ર પધારેલા અને ભક્તો ના આગ્રહ થી ધંધુકા બાજુમાં રંગપુર ગામે ગાદી સ્થાપી. તેમની શિષ્યપરંપરા ના સંતોએ પણ ઘણી જગ્યાએ આશ્રમ સ્થાપેલ છે. આ પરંપરા મારવાડી ભાષા ના શબ્દ  “રામદેવ પોતરા” ઉપર થી આજે શબ્દ બદલાઇ ને રામદેપૂત્રા તરીકે ઓળખાઇ રહી છે.', '1765291824_1001160693.jpg', '2025-12-09 20:20:24'),
(16, 'વારાહી .જિલ્લો. સુરેન્દ્રનગર', 'રામકબીર', 'વર્તમાન મહંત નો કોઈ ઉલ્લેખ કોઈ પાસે હોય તો જણાવવા વિનંતી', '0000000000', 'શ્રી ગુરૂ રામાનંદ્જી એ દક્ષીણ ભારત એટલે કે દ્રવિડ દેશ ના ભક્તિ માર્ગ નો ફેલાવો ઉત્તર ભારત માં કર્યો. એ સમય માં વીદ્વતા સંસ્ક્રૂત ભાષા ને જ વરેલી હતી. આવા સમય માં સંસ્કુત ભાષા ને પંડીતાઈ ને ફગાવી લોક્ભાષા માં ધર્મ નો પ્રચાર કર્યો. જ્ઞાતી અને જાતી ના ભેદભાવ ભુંસી નાખ્યા અને એક સામાજીક ક્રાંતી કરી.રોહીદાસજી કબીરજી વીગેરે ની વૈષ્ણવી દિક્ષા આપી સમાજેક ક્રાંતિ કરી. કબીરજી એ રામ રહીમ ની એકતા નો પયગામ ફેલાવ્યો. તેમના મુખ્ય શિષ્યો માં સુતગોપાલજી એ કાશી માં કબીર સંપ્રદાય સ્થાપ્યો.ધર્મદાસજી એ મધ્યપ્રદેશમાં બંશ ગાદી સ્થાપી.આ સિવાય નારણ્દાસજી, ભગોંદાસજી,સાહેબદાસજી, ટંકસારીજી, કમાલજી, ભગવાનદાસજી, જ્ઞાનદાસજી, વિગેરે મુખ્ય શિષ્યો હતા.તેમાં થી ઘણા શાખા પ્રવર્તાક અને સંપ્રદાય સ્થાપક હતા.રામ ક્બીર, હંસકબીર, સત્તકબીર , નામ કબીર વિગેરે અનેક શાખા છે.\r\nઆમ આપણા સાધુ સમાજ માં રામકબીર સંપ્રદાય ના સંતો કબીર સાધુ તરીકે ઓળખાય છે.', '1765292355_1001160714.jpg', '2025-12-09 20:29:15'),
(17, 'સરપદડ.તાલુકો.પડધરી. જિલ્લો. રાજકોટ', 'સરપદડિયા', 'ભૂપતબાપુ સરપદડિયા', '98257 07024', 'શ્રી ગુરુ રામાનંદ સ્વામી ની પરંપરામાં અનંતાનંદજી ના શિષ્ય ક્રુષ્ણદાસજી પયહારી ગલતા ગાદી જયપુરમાં થયા. તેમનાં મુખ્ય ૨૪ શિષ્યો માં નારાયણદાસજી આધ્યાત્મિક થયા. નારાયણદાસજી મહાન સંત હતા. તેમની શિષ્ય પરંપરા નારાયણદાસ આધ્યાત્મિક દ્વારા થી ઓલખાય છે.તેમના શિષ્ય દયાળદાસજી–>તેમના શિષ્ય લક્ષમીદાસજી—>તેમના શિષ્ય શ્રી હરિદાસજી હતા. આ સંત શ્રી હરિદાસજી એ સરપદડ ગામે ગાદી સ્થાપી. તેમની પરંપરા ના સંતો ત્યારથી સરપદડીયા શાખા થી ઓળખાય છે. તેઓ આધ્યાત્મિક નારણદાસજી દ્વારાના છે. અને રામાવત વૈષ્ણવ છે.', '1765292558_1001160720.jpg', '2025-12-09 20:32:38'),
(18, 'સેંજળ', 'હરિયાણી', 'ટ્રસ્ટ સંચાલિત', '0000000000', 'સર્વપ્રથમ શ્રીમન્નારાયણ ની ઉપદેશ પરંપરામાં હંસ ભગવાન પછી સનકાદિ અને પછી નારદ મુનિ. નારદ મુનિ થી આચાર્ય નીંબાર્ક ને ઉપદેશ મળ્યો તેમ કહેવાય છે.\r\nદક્ષીણ ભારતમાં ગોદાવરી નદી ના કિનારે વૈદુર્યટણ ની બાજુમાં અરુણાશ્રમ સ્થાન એ તેમનું જન્મ સ્થાન છે. પાંચ વર્ષ ની ઉંમરે શ્રી નિંબાર્ક સ્વામિ ના ઉપવિત પ્રસંગમાં દેવર્ષિ નારદ મુનિ એ ઉપસ્થિત થઇ તેમને પ્રેરણા આપી અને ગોપાલ મંત્ર ની દીક્ષા આપી તથા ક્રુષ્ણ ઉપાસના આપી. શ્રી નારદ મુનિએ સનકાદિ પાસેથી મેળવેલું જ્ઞાન તેમને આપ્યું આથી સનકાદિ  સંપ્રદાય કહેવાય છે. યમુના કિનારે ટંટીસ્થાનં વિશ્રામઘાટ ધ્રુવક્ષેત્ર (મથુરામાં) સામે કિનારે તેમનું ગાદી સ્થાન છે. આ સંપ્રદાયના ૧૨ દ્વારા છે.\r\nશ્રી નિમ્બાર્ક સ્વામિ  મહા સમર્થ આચાર્ય  સનકાદિ સંપ્રદાય તેમનાં નામે નિમ્બાર્ક સંપ્રદાય કહેવાયો. નિમ્બાર્ક ની પરંપરામાં આચાર્ય દેવાચાર્ય તથા તેમના બે મુખ્ય શિષ્યો હતાં (૧) સુંદરભટ્ટાચાર્યજી  (૨) વ્રૂજભુષણ દેવાચાર્યજી  આ વ્રૂજભુષણ દેવાચાર્યજી ની પરંપરામાં રસીકદેવજી અને હરિદાસજી સંતો થયા. તેમનાં સ્થાન વ્રુંદાવન આજુબાજુ માં પરિક્રમા રસ્તા પર આવેલાં છે.\r\nહવે શ્રી સુંદર્ભટ્ટ ની પરંપરા જોઇએ તો તેમના થી સોળમા આચાર્ય  કેશવભટ્ટજી, તેમના શિષ્ય શ્રીભટ્ટજી અને તેમનાં મુખ્ય શિષ્ય હરિબ્યાસી હતાં તેમનો જન્મ સવંત ૧૩૦૦ લગભગ છે. તેઓ દ્વારા પ્રવર્તક આચાર્ય હોવાથી તેમની પરંપરા ના સંતો હરિબ્યાસી સંતો તરીકે ઓળખાયા.\r\nઆ સંપ્રદાયમાં ધ્યાનદાસજી આચાર્ય (જેમને આપણે ધ્યાનસ્વામી બાપુ તરિકે ઓળખીયે છીયે)નામનાં સંત સૌરાષ્ટ્રમાં  આવેલા તેઓ ધર્મ પ્રચાર માટે ફરતાં ફરતાં સાવરકુંડલા તાલુકા ના સેંજળ મુકામે જગ્યા સ્થાપી વસેલા ત્યાં તેઓએ જીવતા સમાધિ લીધી છે. ગ્રુહસ્થી હરિયાણી સંતો ના પરીવારજનો સેંજળ મુકામે શ્રી ધ્યાનદાસજી બાપું ની સમાધિએ કર, નૈવૈદ વિગેરે ધરાવે છે.', '1765292656_1001160725.jpg', '2025-12-09 20:34:16'),
(19, 'મેસવાણ', 'મેસવાણિયા શાખા', 'હરકિશનદાસજી બાપુ.', '98791 51122', 'શ્રી ગુરુ રામાનંદજી ના સમર્થ શિષ્ય પીપાજીમહારાજ ની પરંપરામાં શ્રી પીપાજી મહારાજ પ્રથમ પુર્વાશ્રમ્મા તેઓ શક્તિ ઉપાસક હતા. પછી તેઓ એ વૈષ્ણવી દીક્ષા લીધી. તેઓ સમર્થ સંતો માં ગણાય છે. તેઓ દ્વાર પ્રવર્તક સંત હતા. તેમની પરંપરા માં સંત પીપાજી ના શીષ્ય મુલકદાસજી, તેમના શીષ્ય નરસંગદાસજી, તેમના શીષ્ય રામદાસજી, તેમના શીષ્ય ભગવાનદસજી, તેમના શીષ્ય ક્રુષ્ણદાસજી, તેમના શીષ્ય બાલકદાસજી જેવા સંત થયા.શ્રી બાલક્દાસજી મહરાજે સોરઠ માં મેસવાણા ગામે ગાદી શસ્થાપી. તેમની પરંપરામાં સંતો મેસવાણીયા શાખા થી ઓળખાય છે.', '1765293182_1001160741.jpg', '2025-12-09 20:43:02'),
(20, 'ગરણીધામ તાલુકો.બાબરા.જિલ્લો.અમરેલી', 'દેશાણી શાખા', 'રસિકબાપુ દેશાણી', '99242 93093', 'શ્રી કુબાજી સંતની પરંપરા માં શ્રી કુબાજી ના શીષ્ય ગોપાલદાસજી, તેમના શીષ્ય શામદાસજી, તેમના શીષ્ય હિરદાસજી, તેમના શીષ્ય ચેતનદાસજી મહારાજ ના ત્રણ મુખ્ય શિષ્યો  (૧) શ્રી દેશળજી (૨) શ્રી આશરામજી (૩) શ્રી વાઘારામજી તે ત્રણે સંતો શાખા પ્રવર્તક થયા.\r\nસંત શ્રી દેશળજી જેમણે સવંત ૧૭૦૨ ની સાલ મા ગરણી ગામે ગાદી સ્થાપી.શ્રી દેશાણી,શ્રી વાઘાણી અને શ્રી આશાણી આ સહુ સંતો કુબાવત દ્વાર ના છે અને તેઓ રામાવત વૈષ્ણવ છે.', '1765293370_1001160743.jpg', '2025-12-09 20:46:10'),
(21, 'દાણીધાર.તાલુકો.કાલાવડ.જિલ્લો.જામનગર', 'દાણીધારીયા.શાખા.', 'સુખદેવબાપુ', '0000000000', 'શ્રી ગુરુ રામાનંદ સ્વામી ના ૧૨ મુખ્ય શિષ્યો માં અનંતાનંદજી નાં શિષ્ય સમુદાયમાં ૭ મુખ્ય શિષ્યો તુંહિરામ શિષ્ય સમુદાય માં શ્રી નાથજી બાપું એ દાણીધાર માં ગાદી સ્થાપી. તે પરંપરાં નાં સંતો દાણીધારીયા શાખા થી ઓળખાયા. તેઓ તેનુજી દ્વારા ના છે અને રામાવત વૈષ્ણવ છે.\r\nસાધુ સમજમા દાણીધરીયા સમાજ માટે ગુરૂ સ્થાન દાણીધાર આવેલુ છે. આ દાણીધાર  ની જગ્યા કાલાવાડ થી ૧૪ કિલોમીટર દુર છે. તેની નજીક નુ ગામ ટોડા તથા બામણગામ છે.(ધોરાજી ઉપલેટા રોડ, કાલાવાડ તાલુકો)\r\nમુખ્ય સમધી શ્રી નાથજી બાપુ ની છે. શ્રી ગંગારામ બાપુ નો ધુણો તથા મોતીરામ નામનાં કુતરા ની સમાધી છે.', '1765293980_1001160766.jpg', '2025-12-09 20:56:20'),
(22, 'દુધરેજ', 'દૂધરેજીયા શાખા', 'કનીરામજીબાપુ', '0000000000', 'શ્રી ગુરુ રામાનંદ સ્વામીના સમર્થ શિષ્યઓ માં શ્રી કબીરજી ના એક શિષ્ય શ્રી પદ્મનાભજી હતા. શ્રી પદ્મનાભજી ના એક શિષ્ય શ્રી નિલકંઠ સ્વામી, તેમન શિષ્ય શ્રી રૂગનાથજી, તેમન શિષ્ય શ્રીયાદવદાસજી અને તેમના શિષ્ય શ્રી ષટ્પ્રજ્ઞસ્વામિજી. તેમનો જન્મ સવંત ૧૬૬૮ માં થયેલો.\r\nવીક્રમ સવંત ૧૬૬૮ ના અષાઢ માસ ની પુર્ણિમા અને ગુરૂવાર ના દીવસે  મહારાજા યોગરાજ ને ઘરે પુત્ર નો જન્મ થયો તેમનું નામ સામંતસિંહ રાખવા માં આવેલુ. તેમના માતા નું નામ મહારાણી ગંગાદેવી હતું. આ સામંતસિંહ એજ શ્રી ષટ્પ્રજ્ઞસ્વામીજી.\r\nશ્રી ષટ્પ્રજ્ઞ સ્વામિજી મહા સમર્થ આચાર્ય થયા. સવંત ૧૫૯૫ માં દુધરેજ આશ્રમ ની સ્થાપના યોગીરાજ નિલકંઠ આચર્યે કરેલી. આ સમયે ગોંડ્લ મુકામે સવંત ૧૬૨૫ માં પોતે સ્થાપેલા આશ્રમ માં આચર્ય લોહંગજી વિધ્યમાન હતા. ગોંડલ અને દુધરેજ આ બન્ને આચાર્યો વચ્ચે અતિ હેત પ્રીત અને સ્નેહ નીકટ્ત્તમ ભાવના હતી. એમની યદગીરીરૂપે એકજ દાણની ચીરમાંથી બન્ને આચર્યો એ પોત્તપોતાના સ્થાન માં દાતણની એક એક ચીર રોપેલી આ બન્ને વટ્વ્રુક્ષો આજે પણ ગોંડલ અને દુધરેજ મા હસ્તિ ધરવે છે.શ્રી ષટ્પ્રજ્ઞ સ્વામી નો દુધરેજ ની આચર્ય ની ગાદી પર નો સમય ૧૬૯૦ થી ૧૭૮૬ એટલે કે ૯૬ વર્ષ સુધી નો હતો.\r\nશ્રી વડવાળા મંદીર સુરેન્દ્રનગર જીલ્લા ના વઢવાણ તાલુકા માં સુરેન્દ્રનગર થી પાંચ કીલોમીટર નાઅંતરે દુધરેજ ગામે આવેલું છે.આ મંદિરની દક્ષિણ દિશાને અડીને ષષ્ટ્પ્રજ્ઞસ્વામીજી થી આરંભ અત્યાર સુધીના આચાર્યશ્રીઓની ચમત્કારયુક્ત ગણાતી સમાધીઓ આવેલી છે.', '1765294221_1001160774.jpg', '2025-12-09 21:00:21'),
(23, 'ગોંડલ', 'ગોંડલીયા શાખા', 'સીતારામબાપુ', '98248 64198', 'શ્રી લોહંગરી બાપુ\r\nશ્રી ગુરૂ રામાનંદજી ના ૧૨ મુખ્ય શિષ્યો માં પ્રથમ શિષ્ય શ્રી અનંતાનંદજી ની પરંપરા માં તેમનાં જ શિષ્ય ક્રૂષ્ણદાસજી પયહારી કે જે પયહારીબાબા તરીકે ઓળખાય છે. તે ગલતાગાદી (જયપુર) માં થયા. પયહારી બાબા ના શિષ્ય સમુદાય માં મુખ્યત્વે કિલ્હદાસજી, અગ્રદાસજી વિગેરે ૨૪ સંતો હતા, જેમા કિલ્હદાસજી ના શિષ્યો  દેવમુરારી દ્વારા ના કહેવાય છે. શ્રી દેવમુરારીજી ના લોહંગજી નામના શિષ્યે પર્યટન માં વિચરતા ગોંડલ આવ્યા અને ત્યાં જગ્યા બાંધી તેમની પરંપરા ના સંતો ગોંડલીયા કહેવાયા.\r\nગોંડલમાં ગુરૂ લોહંગજી મહારાજ કે જેમનું પુરું નામ શ્રી જીવણદાસજી લોહંગરી હતું\r\nતેમના શીષ્ય પરિવાર માં શ્રી રાદાસજી નો પરિવાર ગોંડલ ના સ્થાન પર છે. મહાત્મા મુળદાસજી એ અમરેલી માં જગ્યા સ્થાપી. શ્રી નથુરામજી એ ખંભળિયા (શેલ) માં જગ્યા સ્થાપી. શ્રી ભાવદાસજી એ ધોલેરા માં જગ્યા સ્થાપેલ છે. આ સીવાય નારણદાસજી, અમરદાસજી, વાલદાસજી, રામદાસજી, ધ્યાનદાસજી વીગેરે ૨૬ સંતો  હતા જેમણે આ પરંપરા માં સૌરાષ્ટ્ર માં જુદા જુદા સ્થળે જગ્યા સ્થાપના કરેલી.આ પરંપરામાં પોતાનાં ગુરુસ્થાનો માં કર નૈવૈદ વિગેરે વિધિ થાય છે. પરંતુ આધ્યગુરૂ સ્થાન ગોંડલ મુકામે છે.', '1765294360_1001160502.jpg', '2025-12-09 21:02:40'),
(24, 'ધ્રંગ', 'કાપડી શાખા', 'મુળજી ડાડા', '99782 20789', 'ગુજરાત ની ભુમી પર સેવાનો ભેખ લઇ ઘણા સંતો થઇ ગયા જેમણે બીમાર, ગરીબ, પશુપંખી ની સેવા માં જીવન વીતાવી માનવતા નુ કાર્ય કરેલુ છે. આવાજ એક સંત શ્રી મેકણજી એ ગીરનારી સંતો ની આજ્ઞા થી ક્ચ્છ ના રણ પ્રદેશ માં પોતાનું સેવા કાર્ય વિસ્તાર્યું. અંહિ ગુરુ ગંગારાજા પાસેથી ઉપદેશ લીધો અને કાપડી પંથ ને વધુ પ્રકાશમાં લાવ્યા.શ્રી મેકણજી મહાન સમર્થ સંત હતા. જેથી તેમના કાપડી પંથ માં એક નવી શાખા શરું થઈ જે મેકાપંથી નામે ઓળખાય છે.\r\nકાપડી સંતો નું મુળ સ્થાન ક્ચ્છમાં રહેલું છે. શ્રી લક્ષમણજી થી કચ્છના આ પંથ ના આદિ પુરુષ શ્રી જસારાજા ને ભેખ મળેલો, તેમની પરંપરા માં શ્રી ગંગારાજા થયા અને તેમના શિષ્ય શ્રી મેકણજી મહાન સંત થયા. સંપ્રદાયો ના તાણા વાણા થી દુર રહી તેમણે તેમનું જીવન પ્રાણી માત્ર ની મહાન સેવા ના માર્ગે પુર્ણ કર્યુ. સવંત ૧૭૮૬ માં ધ્રંગલોડાઈ સ્થળે જીવતા સમાધી લિધી. તેમની સાથે ૧૧ ભક્તો એ પણ સમાધી લીધી. લાલદાસ અને મોતીરામ નામના પશુ એ પણ સમાધી લીધેલી. આજે પણ આ સ્થળે ૧૧ સમાધી ના દર્શન છે. આ પરંપરા માં સૌરાષ્ટ્ર ગુજરત માં કાપડી સંતો ના ઘણા સ્થાન આવેલા છે. તેમની શિષ્ય પરંપરા કાપડી શાખા થી ઓળખાય છે.', '1765294505_1001160779.jpg', '2025-12-09 21:05:05');
