INSERT INTO `tbl_news` (`id`, `title`, `description`, `image`, `created_at`) VALUES
(7, 'ધાર્મિક સમાચાર – સમાધિ પૂજન, સંતમિલન અને મહાપ્રસાદનો વિશાળ ધાર્મિક કાર્યક્રમ સફળતાપૂર્વક પૂર્ણ ', 'સમાધિસ્થ સાધુશ્રી હીરાબેન વિનોદભાઈ ગોંડલીયા (ઉ.વ. 70) એ સંવત 2082, માગશર સુદ 2 – શનિવાર, તા. 22-11-2025ના રોજ શ્રીરામચરણ પામ્યા હતા. તેમના આત્મકલ્યાણાર્થે સંતમિલન – સંતભોજન – ભંડારોનું ભવ્ય આયોજન સંવત 2082, માગશર સુદ 12 મંગળવાર, તા. 02-12-2025ના રોજ કરવામાં આવ્યું હતું.આ પવિત્ર પ્રસંગે ધાર્મિક વાતાવરણ, સંતવાણી, ધર્મસભા, મહાપ્રસાદ તેમજ પરંપરાગત સમાધિ પૂજનનું સુવિધાસભર આયોજન કરવામાં આવ્યું હતું. કાર્યક્રમ દરમિયાન ભક્તિભાવ અને આધ્યાત્મિક ઉર્જાનો અદભુત સંગમ જોવા મળ્યો.\r\n\r\nપવિત્ર સંતદર્શન – ઉપસ્થિત સંત વિભૂતિઓ\r\nઆ અનન્ય ધાર્મિક પ્રસંગે અનેક મહાનુભવ સંતો તથા સંતસમાજની પ્રેરક ઉપસ્થિતિ રહી, જેમાં મુખ્યરૂપે—\r\n૫. પૂ. મહામંડલેશ્વર 1008 પૂ. શ્રી મુળદાસજીબાપુ મેસવાણીયા, રામ મઢી – સુરત\r\nમહંત શ્રી વામનદાસજીબાપુ ગોંડલીયા, સાકરીયા હનુમાનજી – કુંકાવાવ\r\nશ્રી વિઠ્ઠલદાસ બાલકદાસ કાપડી, જુનાગઢ\r\nમહંત શ્રી શાંતિરામજીબાપુ ગોંડલીયા, અનિડા\r\nસંત શ્રી પ્રેમદાસજી જમનાદાસજી ગોંડલીયા, દેવગામ\r\nસંત શ્રી ચેતનદાસજી હરદેવદાસજી દુધરેજીયા, વાસાવડ\r\nસંત શ્રી દેવીદાસજી જીવારામજી કાપડી, દેવળીયા\r\nસાધુ શ્રી પિયુષભાઈ રવિરામજી ગોંડલીયા, કુંકાવાવ\r\nકોટવાળ શ્રી રમેશભાઈ આત્મારામજી દેશાણી, શાપર\r\nઆ તમામ વિભૂતિ સંતોના આશીર્વચન અને ઉપસ્થિતિથી કાર્યક્રમને વિશેષ દિવ્યતા પ્રાપ્ત થઈ.\r\n\r\n સંત-મહંતોનું અભિવાદન\r\nઆ પવિત્ર પ્રસંગે આમંત્રિત સર્વે સંત-મહંતો તથા પરિવારજનોનું અભિવાદન નીચેના સંતોએ સૌજન્યપૂર્ણ રીતે કર્યું:\r\nસાધુ શ્રી વિનોદભાઈ બાલકદાસજી ગોંડલીયા\r\nસાધુ શ્રી ગંગારામજી બાલકદાસજી ગોંડલીયા\r\nસાધુ શ્રી કિશોરભાઈ બાલકદાસજી ગોંડલીયા\r\nસાધુ શ્રી નિલેશભાઈ શાંતિરામજી ગોંડલીયા\r\nસાધુ શ્રી અલ્પેશભાઈ શાંતિરામજી ગોંડલીયા\r\nસાધુ શ્રી જનકભાઈ ગંગારામજી ગોંડલીયા\r\nકાર્યક્રમ સંચાલન\r\nસમગ્ર કાર્યક્રમનું સુવ્યવસ્થિત સંચાલન\r\nશ્રી વિઠ્ઠલદાસજી બાળકદાસજી કાપડી – જુનાગઢ\r\nદ્વારા સરસ રીતે કરવામાં આવ્યું.\r\n\r\nઉપસંહાર\r\nધાર્મિક ભાવના, સદભાવના અને સંતસમાજના આશીર્વાદોથી પરિપૂર્ણ આ પ્રસંગ સમાધિષ્ઠ માતાજી હીરાબેન વિનોદભાઈ ગોંડલીયાના આત્મકલ્યાણને અર્પિત એક શુભ કાર્યરૂપ બન્યો. સમગ્ર સમાજે ભક્તિભાવ સાથે ભાગ લીધો અને કાર્યક્રમ સફળતાપૂર્વક પૂર્ણ થયો.', '1764915156_5934_1001142413.jpg,1764915156_4455_1001142585.jpg,1764915156_5395_1001142422.jpg,1764915156_6062_1001144443.jpg,1764915156_5061_1001142425.jpg', '2025-12-05 11:42:36'),
(6, 'સંસ્કાર, સેવા અને સ્નેહનું પવિત્ર યજ્ઞ', 'સાધુ સમાજની 18 દીકરીઓનો સમૂહ લગ્નોત્સવ\r\nતારીખ : 13 ફેબ્રુઆરી 2026\r\nસમાજને સંસ્કાર, સામાજિક સમાનતા અને એકતાના પવિત્ર સૂત્રમાં બાંધતા કાર્યક્રમો આપણું સામાજિક જીવન વધુ સુંદર બનાવે છે. તેમાં પણ સમૂહ લગ્નોત્સવ એ સેવા અને સદભાવનાનું અનોખું પ્રતિક છે — જ્યાં કોઇ એક પરિવારમાં નહીં, પરંતુ આખા સમાજના હૃદયમાં આનંદના દીવા પ્રગટે છે.આ વર્ષે પણ શ્રી તુલસીપ્રભુ ધામ રાભડા આશ્રમ એક અનોખા અને મહાન સેવાયજ્ઞનો સાક્ષી બનવા જઈ રહ્યો છે. પૂજ્ય યુવા કથાકાર શ્રી રવિરામબાપુ હરિયાણીની પ્રેરણાથી અને સાધુ સમાજના આશીર્વાદોથી 18 દીકરીઓના સમૂહ લગ્નોત્સવનું ભવ્ય આયોજન કરવામાં આવ્યું છે.\r\n', '1764686050_1001128670.jpg', '2025-12-02 20:04:10'),
(8, 'કેશોદના મેસવાણ ગામે બાલક સ્વામી બાપુની ૭૩૨મી જન્મજયંતિની ભવ્ય ઉજવણી સમાધિસ્થાને શિષ્યો–ભાવિકોની મોટી સંખ્યામાં ઉપસ્થિતિ', 'કેશોદ તાલુકાના મેસવાણ ગામે દત્ત અવતાર રૂપે પૂજ્ય સિદ્ધ સંત શ્રી બાલક સ્વામી બાપુની ૭૩૨મી જન્મ જયંતિનો પાવન પ્રસંગ આ વર્ષે પણ અત્યંત ભક્તિભાવ અને હર્ષોલ્લાસ સાથે ઉજવાયો હતો. માગશર સુદ પુનમ, તા. ૪ ડિસેમ્બર ૨૦૨૫ના મહાપ્રસંગે મેસવાણ નદીકાંઠે આવેલા બાલક સ્વામી બાપુના સમાધિ સ્થાન પર સર્વત્ર ભક્તિનો માહોલ છવાઈ ગયો હતો.\r\nબાપુના અનન્ય શિષ્યો, મેસવાણીયા સાધુ સમાજ, મહિયા ક્ષત્રિય સમાજ સહિત મેસવાણ ગામના ભક્તજનોએ પરંપરાગત રિવાજ મુજબ આ પવિત્ર તિથિને ધામધૂમથી ઉજવી હતી. કાર્યક્રમને મેસવાણ ગામના મહંત શ્રી ૧૦૦૮ મહામંડલેશ્વર હરકિશનબાપુના આશીર્વાદ પ્રાપ્ત રહ્યા હતા.\r\nદિવસ દરમિયાન પાદુકા પૂજન, ધજા–સામૈયા તથા વિવિધ ધાર્મિક વિધિઓ યોજાયા હતા. સાંજે ભવ્ય મહાઆરતીનું આયોજન કરવામાં આવ્યું, જેમાં ગ્રામજનો અને ભાવિકોએ બહોળી સંખ્યામાં ઉપસ્થિત રહી દિવ્ય વાતાવરણનો લાભ લીધો હતો. મહાપ્રસાદમાં પણ ભક્તોની વિશાળ સંખ્યા જોડાઈ હતી.\r\nરાત્રિએ રામદેવજી મહારાજના પાઠ પૂજન બાદ ભવ્ય સંતવાણી ડાયરા યોજાયો હતો, જેમાં છેલાવડા, મયુરીબા પારેડી, જયુભા ગઢવી, મનીષાબેન ભાલિયા અને ચંદુભાઈ ડાભી સહિતના સાજિંદા કલાકારોની સંગતમાં ડાયરો એક યાદગાર રાત્રી બની રહ્યો હતો.\r\nઆ સમગ્ર ધાર્મિક મહોત્સવને સફળ બનાવવા કલાકાર ધીરૂભાઇ અશ્વિનભાઇ બાબરીયા, રાજભા બાબરીયા અને તેમની ટીમ દ્વારા વિશેષ મહેનત કરવામાં આવી હતી.', '1764993574_8106_1001151557.jpg', '2025-12-06 09:29:34'),
(9, 'સાવરકુંડલા ના યુવાન હરિયાણી મિત રાજેશભાઈની ઉર્જાસભર સિદ્ધિ જિલ્લાકક્ષા યુવા મહોત્સવમાં પ્રથમ ક્રમે વિજયનો કીર્તિમાન', 'અમરેલી જિલ્લામાં શ્રી કે.કે. પારેખ અને મહેતા આર.પી. વિદ્યાલય, અમરેલીના આયોજન હેઠળ જિલ્લા કક્ષાનો યુવા મહોત્સવ ભવ્ય રીતે પૂર્ણ થયો હતો. વિવિધ સાંસ્કૃતિક અને સાહિત્યિક પ્રતિસ્પર્ધાઓથી સજ્જ આ મહોત્સવમાં જિલ્લા ભરના પ્રતિભાશાળી યુવાનો એ ઉર્જાપૂર્વક ભાગ લીધો હતો.આ મહોત્સવની દુહા–છંદ–ચોપાઈ સ્પર્ધા માં સાવરકુંડલાના યુવાન હરિયાણી મિત રાજેશભાઈ એ પોતાના કાવ્યકૌશલ્ય અને સર્જનાત્મકતાના આધારે પ્રથમ સ્થાન હાંસલ કરી સાવરકુંડલાનું નામ ગૌરવપૂર્વક રોશન કર્યું છે.મિતભાઈની આ ઝળહળતી સિદ્ધિ બદલ સમગ્ર સાવરકુંડલા તેમજ મિત્રવર્તુળ તરફથી શુભેચ્છાઓ અને અભિનંદનનો વરસાદ વરસી રહ્યો છે.\r\nહવે મિત રાજેશભાઈ આગામી સમયમાં પ્રદેશકક્ષા ના યુવા મહોત્સવમાં પ્રતિસ્પર્ધા કરવા જઈ રહ્યા છે. તેમને આગામી ચરણ માટે હાર્દિક શુભકામનાઓ તથા તેજસ્વી સફળતાની કામના.યુવાનો માટે પ્રેરણારૂપ એવી તેમની આ સિદ્ધિ ખરેખર વખાણને લાયક છે.', '1765075475_9032_1001153980.jpg,1765075475_3349_1001153981.jpg', '2025-12-07 08:14:35'),
(10, 'મહુવા તાલુકાના રાતોલના પાર્થ હરિયાણીની સૌરાષ્ટ્ર સ્તરે ભજન સ્પર્ધામાં ગૌરવસભર સિદ્ધિ', 'મહુવા તાલુકાના રાતોલ ગામના પ્રતિભાશાળી યુવાન પાર્થ અરૂણભાઈ હરિયાણીએ સૌરાષ્ટ્ર પ્રદેશકક્ષા કલા મહાકુંભ ૨૦૨૫–૨૬ અંતર્ગત યોજાયેલી ભજન સ્પર્ધામાં પ્રથમ ક્રમાંક પ્રાપ્ત કરી નોંધપાત્ર સફળતા હાંસલ કરી છે. આ સિદ્ધિથી રાતોલ ગામ સહિત સમગ્ર મહુવા તાલુકામાં ગૌરવની લાગણી વ્યાપી છે.\r\nસર મંદિર, મહુવા સાથે સંકળાયેલા પાર્થ અરૂણભાઈએ સંગીતના નિયમિત અધ્યયન અને ગાયકીની સમર્પિત સાધના દ્વારા આ સ્પર્ધામાં ઉત્કૃષ્ટ રજૂઆત કરી હતી. તેમણે શુદ્ધ સ્વર, સુંદર લયબદ્ધતા અને ભાવસભર ભક્તિપ્રવાહથી ભરપૂર ભજન રજૂ કરી જજોની વિશેષ પ્રશંસા મેળવી હતી.\r\nપ્રદેશકક્ષા પર મળેલી આ સિદ્ધિને કારણે સ્થાનિક સ્તરે શિક્ષણ અને કલા ક્ષેત્રે યુવા પેઢીમાં નવી પ્રેરણા જાગી છે. પાર્થ અરૂણભાઈની સફળતા ગ્રામજનો તથા સંસ્કૃતિપ્રેમી વર્ગ માટે ગૌરવરૂપ બની છે અને તેમની પ્રતિભા સતત વિકસતી હોવાનો સાબિતી આપે છે.\r\nકલા મહાકુંભ સ્પર્ધા–૨૦૨૫ અમરેલી ખાતે તા. ૬ થી ૮ ડિસેમ્બર ૨૦૨૪ દરમિયાન શાંતાબા મેડિકલ ઓડિટોરીયમ હોલ ખાતે યોજાઈ હતી. પાર્થ અરૂણભાઈની આ સિદ્ધિથી વિસ્તારમાં કલાત્મક પ્રવૃત્તિઓને નવી દિશા અને પ્રોત્સાહન મળશે તેવી આશા વ્યક્ત કરવામાં આવી રહી છે.', '1765591854_7373_1001169512.jpg', '2025-12-13 07:40:54'),
(11, 'ભાવનગર.નિઃશુલ્ક સ્પર્ધાત્મક પરીક્ષા વર્ગોનો શુભ પ્રારંભ', 'શ્રી ભાવનગર વૈષ્ણવ સાધુ (માર્ગી/બા.વૈ.) સમાજના ઉપક્રમે શ્રી હનુમંત વિદ્યાર્થી ભવન, ભાવનગર ખાતે સમાજના દીકરા-દીકરીઓના ઉજ્જવળ ભવિષ્ય માટે શરૂ કરાયેલા સ્પર્ધાત્મક પરીક્ષાઓના નિઃશુલ્ક વર્ગોનો આજરોજ તા. ૧૪/૧૨/૨૦૨૫, રવિવારના રોજ સવારે ૦૯:૦૦ કલાકે દીપ પ્રાગટ્ય તથા શ્રી હનુમાનજી મહારાજના ચાલીસાના સમૂહ પાઠ સાથે ભવ્ય અને ધાર્મિક માહોલમાં શુભારંભ કરવામાં આવ્યો.\r\n\r\nઉદ્દઘાટન સત્ર દરમિયાન શ્રી હનુમંત વિદ્યાર્થી ભવનના વિદ્યાર્થીઓના વરદહસ્તે દીપ પ્રાગટ્ય કરવામાં આવ્યું તેમજ પધારેલા મહેમાનો અને વર્ગો લેનાર વિદ્વાન શ્રીઓનું હાર્દિક સ્વાગત કરવામાં આવ્યું. કાર્યક્રમનું શાબ્દિક સ્વાગત શ્રી હરૂભાઈ ગોંડલીયાએ કર્યું. એકેડમી સંબંધિત વિગતવાર માહિતી શ્રી જુગલકિશોરભાઈ હરિયાણી દ્વારા આપવામાં આવી હતી, જ્યારે શ્રી હિરેનભાઈ દુધરેજીયાએ વર્ગો લેનાર વિદ્વાન શ્રીઓનો વિસ્તૃત પરિચય કરાવ્યો.\r\n\r\nઆ પ્રસંગે શ્રી વિનોદભાઈ દાણીધરીયાએ સૌનો આભાર માન્યો હતો. સમગ્ર કાર્યક્રમનું સંચાલન શ્રી ભગીરથભાઈ કબીર દ્વારા સુચારુ રીતે કરવામાં આવ્યું. ઉપરાંત કારોબારી સમિતિના સભ્યોએ ઉપસ્થિત રહી વિદ્યાર્થીઓને પ્રોત્સાહન પૂરું પાડ્યું હતું.\r\n\r\nઉલ્લેખનીય છે કે આ નિઃશુલ્ક વર્ગો દર રવિવારે નિયમિત રીતે યોજાશે. જેમાં સમાજના તેમજ અન્ય સમાજના અનુભવી અને વિદ્વાન શિક્ષકો દ્વારા માનદ સેવા આપવામાં આવશે. આ વિદ્વાન શ્રીઓમાં શ્રી જુગલકિશોરભાઈ હરિયાણી (વંદે માતરમ એજ્યુકેશન હબ, ભાવનગર), શ્રી માધવભાઈ કાપડી, શ્રી હિરેનભાઈ દુધરેજીયા, શ્રી રૂચીબેન દુધરેજીયા, શ્રી ધ્રુવભાઈ ગોંડલીયા, શ્રી ભગીરથભાઈ કબીર, શ્રી વિનોદભાઈ દાણીધારીયા, શ્રી ભરતભાઈ દેશાણી, શ્રી કિશનભાઈ બરોલીયા, શ્રી દીપકભાઈ દુધરેજીયા સહિતના વિદ્વાનો સામેલ છે.\r\n\r\nસમાજ દ્વારા શરૂ કરાયેલ આ મહત્વપૂર્ણ પહેલથી સ્પર્ધાત્મક પરીક્ષાની તૈયારી કરતા અનેક વિદ્યાર્થીઓને લાભ મળશે અને તેમના ઉજ્જવળ ભવિષ્યના માર્ગને નવી દિશા મળશે.\r\n', '1765729156_3938_1001174035.jpg,1765729156_9213_1001173781.jpg,1765729156_7901_1001173764.jpg,1765729156_1813_1001173767.jpg,1765729156_9916_1001173770.jpg,1765729156_7681_1001173787.jpg,1765729156_2979_1001173790.jpg,1765729156_5174_1001173775.jpg,1765729156_6003_1001173778.jpg', '2025-12-14 21:49:16'),
(12, 'જુનાગઢ ખાતે સમાધિસ્થ સાધુશ્રી અનંતભાઈ પ્રભુદાસભાઈ કાપડીના મોક્ષાર્થે સંત ભોજન ભંડારાનું આયોજન સંપન્ન ', 'જુનાગઢ મુકામે કુળદેવી શ્રી હિંગળાજ માતાજી તથા ડાડા મેકરણના આશીર્વાદ સાથે દુઃખભર્યા હૃદયે જણાવવામાં આવે છે કે, જુનાગઢ નિવાસી જીગ્નેશભાઈ કાપડી તથા દેવેનભાઈ કાપડીના પિતા, સમાધિસ્થ સાધુશ્રી અનંતભાઈ પ્રભુદાસભાઈ કાપડી સવંત ૨૦૮૨ માગશર વદ-૨, તા. ૦૬/૧૨/૨૦૨૫ (શનિવાર)ના રોજ રામચરણ પામ્યા હતા.\r\n\r\nતેમના પાવન આત્માના મોક્ષાર્થે આજરોજ તા. ૧૬/૧૨/૨૦૨૫ ના રોજ જુનાગઢ ખાતે સંત ભોજન ભંડારાનું ભવ્ય તથા સુંદર આયોજન કરવામાં આવ્યું હતું. આ કાર્યક્રમમાં સંતો, મહંતો, સમાજના અગ્રણીઓ તેમજ દિવંગતના પરિવારજનોની વિશાળ સંખ્યામાં ઉપસ્થિતિ નોંધપાત્ર રહી હતી.\r\n\r\nઆ પ્રસંગે મહામંડલેશ્વર ૧૦૦૮ શ્રી શ્રી જગજીવનબાપુ, મહામંડલેશ્વર ૧૦૦૮ શ્રી શ્રી અજાયબાપુ (સવરામંડપ) તેમજ સામાજિક અગ્રણી શ્રી આર.કે. સાહેબ દૂધરેજીયાની પ્રેરક ઉપસ્થિતિથી કાર્યક્રમ વધુ ગૌરવમય બન્યો હતો.\r\n\r\nકાર્યક્રમમાં પધારેલા સર્વે સંતો તથા આમંત્રિત મહેમાનોનું આત્મીય અભિવાદન શ્રી ભુપેન્દ્રભાઈ સી. કાપડી, શ્રી રાજુભાઈ સી. કાપડી, શ્રી દિપકભાઈ વી. કાપડી, શ્રી જીગ્નેશભાઈ એ. કાપડી, શ્રી દિનેશભાઈ એલ. કાપડી તથા શ્રી મયુરભાઈ એલ. કાપડી દ્વારા કરવામાં આવ્યું હતું.\r\n\r\nશુભ સ્થળ:\r\nમાનસબાગ, ગીરનાર દરવાજે, દન મારબલ સામે, જુનાગઢ\r\n\r\nઆ સમગ્ર આયોજન ભક્તિભાવ, શાંતિ અને સંવેદનાથી ભરપૂર રહ્યું હતું, જેમાં ઉપસ્થિત તમામ ભાવિકોએ દિવંગત આત્માને શ્રદ્ધાંજલિ અર્પી હતી.', '1765874732_5008_1001178331.jpg,1765874732_6423_1001178334.jpg,1765874732_3483_1001178349.jpg,1765874732_2558_1001178355.jpg,1765874732_7919_1001178379.jpg,1765874732_9630_1001178391.jpg,1765874732_9452_1001178385.jpg', '2025-12-16 14:15:32'),
(13, 'વૈષ્ણવ સાધુ સમાજ મહુવા – મહિલા સત્સંગ મંડળની પ્રશંસનીય સમાજસેવા', 'વૈષ્ણવ સાધુ સમાજ મહુવા ખાતે સમાજની બહેનો તથા માતાઓ દ્વારા વર્ષ 2014 માં મહિલા સત્સંગ મંડળની સ્થાપના કરવામાં આવી હતી. આ સત્સંગ મંડળ દ્વારા નિયમિત રીતે સત્સંગ, ભેટ, બચત, ચડાવો, થાળ, પૂજા તથા આરતી જેવા ધાર્મિક કાર્યક્રમો યોજાઈ સમાજહિત માટે પાઈ પાઈ બચત એકઠી કરવામાં આવતી હતી.\r\nકોરોના મહામારી આવવા સુધી આ સત્સંગ મંડળના કાર્યક્રમો સતત અને સુચારુ રીતે ચાલતા રહ્યા હતા. પરંતુ કોરોનાના કારણે બે વર્ષ સુધી સત્સંગ કાર્યક્રમો બંધ રહેતા, ત્યારબાદ મહિલા સત્સંગ મંડળ પાસે સમાજની બચત પ્રસાદી સ્વરૂપે અંદાજે રૂ. 50,000/- જેવી રકમ જમા રહી હતી.\r\nઆ રકમનો યોગ્ય ઉપયોગ સમાજહિત માટે કરવો તે હેતુથી બહેનો તથા માતાઓ દ્વારા વારંવાર ચર્ચા-વિમર્શ કરવામાં આવ્યો. સમાજની વાડીમાં વિવિધ ઉપયોગી વસ્તુઓ આપવા અંગે અનેક વિચાર આવ્યા, પરંતુ અંતે સર્વસંમતિથી એક મહત્વપૂર્ણ અને વ્યવહારુ નિર્ણય લેવામાં આવ્યો.\r\nલગ્ન તથા અન્ય માંગલિક પ્રસંગોમાં વર તથા કન્યા પક્ષના રૂમમાં કીમતી સામાનની સુરક્ષા એક મોટી સમસ્યા બની રહેતી હોય છે. ઘણી વખત કીમતી વસ્તુઓ સાચવવા માટે અલગ વ્યક્તિ રાખવી પડે છે, જેના કારણે તેઓ પ્રસંગનો આનંદ માણી શકતા નથી. તેમજ આજકાલ ચોરીની ઘટનાઓ પણ અવારનવાર બનતી હોય છે, જેના કારણે લોકો કીમતી વસ્તુઓ પ્રસંગે લાવવા માટે સંકોચ અનુભવે છે.\r\nઆ સમસ્યાને ધ્યાનમાં રાખીને મહિલા સત્સંગ મંડળ દ્વારા સમાજની વાડી સ્થિત વર અને કન્યા પક્ષના રૂમમાં કીમતી સામાન સુરક્ષિત રીતે રાખી શકાય તે માટે બે મજબૂત કબાટ વિથ તિજોરી લોક ભેટ આપવા નિર્ણય કરવામાં આવ્યો.\r\nતે મુજબ બહેનો દ્વારા સ્પેશિયલ ઓર્ડરથી સારામાં સારા ગેજ તથા તિજોરી લોક સાથે તૈયાર કરાયેલા રૂ. 23,000/- કિંમતના, 135 કિલો વજનના એક કબાટ મુજબ કુલ બે કબાટ (કુલ ખર્ચ રૂ. 46,000/- અને કુલ વજન 270 કિલો) આજ રોજ તા. 15/12/2025 ના રોજ શ્રી હનુમંત બાગ, મહુવા ખાતે સમાજની વાડીમાં ભેટ અર્પણ કરવામાં આવ્યા.\r\nઆ સેવાભાવી અને દુરંદેશી નિર્ણયને શ્રી હનુમંત બાગ ટ્રસ્ટી મંડળે હર્ષભેર વધાવી લીધો હતો તથા ભેટ પ્રસાદી સહર્ષ સ્વીકારી મહિલા સત્સંગ મંડળની માતાઓ તથા બહેનોનો હૃદયપૂર્વક આભાર વ્યક્ત કર્યો હતો.\r\nમહિલા સત્સંગ મંડળ દ્વારા કરવામાં આવેલી આ સુંદર સેવા સમાજ માટે દીર્ઘકાળ સુધી ઉપયોગી સાબિત થશે અને અન્ય માટે પણ પ્રેરણારૂપ બનશે.', '1765894770_3433_1001179107.jpg', '2025-12-16 19:49:30'),
(14, 'સાવરકુંડલામાં વકીલ મંડળના મંત્રી તરીકે એડવોકેટ મેહુલદાસ ગોંડલીયાની બિનહરીફ વરણી', 'ભેંકરા ગામ નું ગૌરવ એવા એડવોકેટ ગોંડલિયા મેહુલદાસ પ્રવિણદાસ (વકીલ)\r\n\r\nસાવરકુંડલા બાર એસોસીએશન (વકીલ મંડળ)ની તાજેતરમાં યોજાયેલી ચૂંટણીમાં યુવા અને ઉત્સાહી એડવોકેટ મેહુલદાસ પ્રવિણદાસ ગોંડલીયાની મંત્રી પદ માટે બિનહરીફ વરણી થતાં સમગ્ર વકીલ વર્ગમાં આનંદ અને ઉત્સાહનો માહોલ જોવા મળ્યો હતો.\r\nએડવોકેટ મેહુલદાસ ગોંડલીયા પોતાની કાર્યશૈલી, સહકારભાવ અને કાયદાકીય સમજ માટે વકીલ સમુદાયમાં વિશેષ ઓળખ ધરાવે છે. તેમની બિનહરીફ વરણી એ વકીલ મંડળ દ્વારા તેમની કાર્યક્ષમતામાં મૂકાયેલા વિશ્વાસનું પ્રતીક માનવામાં આવે છે.\r\nનવાં મંત્રી તરીકે એડવોકેટ ગોંડલીયાએ વકીલ મંડળની એકતા મજબૂત કરવી, વકીલોના હિતલક્ષી પ્રશ્નો માટે સક્રિય રીતે કાર્ય કરવું તથા બાર અને બેન્ચ વચ્ચે સુમેળ વધે તેવા પ્રયત્નો કરવાની પ્રતિબદ્ધતા વ્યક્ત કરી છે.\r\nઆ અવસરે સાવરકુંડલા બાર \r\n\r\n\r\nએસોસીએશનના વરિષ્ઠ વકીલો, સહયોગી સભ્યો અને મિત્રો દ્વારા તેમને હાર્દિક શુભેચ્છાઓ પાઠવવામાં આવી હતી અને તેમના કાર્યકાળ દરમિયાન વકીલ મંડળ નવી ઊંચાઈઓ હાંસલ કરે તેવી શુભકામનાઓ વ્યક્ત કરવામાં આવી હતી.', '1766071541_7056_1001184431.jpg', '2025-12-18 20:55:41'),
(15, 'ખાંભા વકીલ મંડળના સેક્રેટરી તરીકે એડવોકેટ તથા નોટરી શ્રી રાજુભાઈ હરિયાણીની સતત 12મી વાર વરણી', 'ખાંભા તાલુકાના સિનિયર, સેવાભાવી એડવોકેટ તથા ભારત સરકાર દ્વારા નિયુક્ત નોટરી શ્રી રાજુભાઈ હરિયાણીની ખાંભા વકીલ મંડળના સેક્રેટરી તરીકે સતત 12મી વાર વરણી થતા સમગ્ર ખાંભા તાલુકામાં આનંદ અને ગૌરવની લાગણી વ્યાપી છે.\r\n\r\nશ્રી રાજુભાઈ હરિયાણી માત્ર કાનૂની ક્ષેત્રે જ નહીં પરંતુ સામાજિક જીવનમાં પણ આગવી ઓળખ ધરાવે છે. તેઓ ખાંભા વિસ્તારમાં મૂંગા પશુ-પક્ષીઓની સતત સેવા, શહેરના દરેક ધાર્મિક કાર્ય, સેવાકીય પ્રવૃત્તિઓ તેમજ શૈક્ષણિક ક્ષેત્રના કાર્યોમાં હંમેશા અગ્રેસર રહ્યા છે. તાલુકાની અનેક સેવાભાવી તથા ધાર્મિક સંસ્થાઓ અને વિવિધ ટ્રસ્ટોમાં તેઓ નિસ્વાર્થ અને અવિરત સેવા આપી રહ્યા છે.\r\n\r\nવડીલ હોય કે યુવાન, સૌને સાથે લઈને ચાલવાની તેમની આગવી કાર્યશૈલીને કારણે તેઓ સૌના પ્રિય અને લોકલાડીલા બની રહ્યા છે. તેમની કાર્યક્ષમતા, નિષ્ઠા અને સેવાભાવના પરિણામે ખાંભા વકીલ મંડળે તેમના પર ફરી એકવાર વિશ્વાસ મૂકી તેમને સેક્રેટરી તરીકે જવાબદારી સોંપી છે.\r\n\r\nઆ પ્રસંગે ખાંભા તાલુકાભરના આગેવાનો, વિવિધ જ્ઞાતિના પ્રતિનિધિઓ તેમજ અનેક સંસ્થાઓના હોદ્દેદારો દ્વારા શ્રી રાજુભાઈ હરિયાણીને અભિનંદન અને શુભેચ્છાઓ પાઠવવામાં આવી છે તથા તેમના કાર્ય માટે ગૌરવની લાગણી વ્યક્ત કરવામાં આવી છે.', '1766196172_5346_1001187693.jpg', '2025-12-20 07:32:52'),
(16, '“શ્રી વૈષ્ણવ સાધુ માર્ગી વૈરાગી પરિવારની બંને દીકરીઓએ ઉત્કૃષ્ટ પરિણામ સાથે પરિવાર અને સમાજનું ગૌરવ વધાર્યું છે.”', 'રાણાવાવ તા. ૧૬ – ભક્ત કવિ નરસિંહ મહેતા યુનિવર્સિટી, જૂનાગઢ દ્વારા સપ્ટેમ્બર-૨૦૨૫માં લેવાયેલ બી.એ. સેમેસ્ટર-૩ની પરીક્ષાનું પરિણામ તાજેતરમાં જાહેર થયું છે. જેમાં સરકારી વિનયન કોલેજ, રાણાવાવનું ૯૨.૩૧% જેટલું ઊંચું અને નોંધપાત્ર પરિણામ નોંધાયું છે.\r\nજેમાં કોલેજના વિદ્યાર્થીઓનું વ્યક્તિગત પરિણામ પણ અત્યંત ધ્યાનાકર્ષક રહ્યું છે. મનોવિજ્ઞાન વિષયમાં\r\n🔹 તૃતીય ક્રમાંકે મયુરી લખુરામજી દુધરેજીયાએ ૮૧.૮૭%\r\n🔹 ચતુર્થ ક્રમાંકે ખુશી ગિરીશભાઈ દુધરેજીયાએ ૮૦.૦૦%\r\nગુણ પ્રાપ્ત કરી કોલેજ, પરિવાર અને સમાજનું ગૌરવ વધાર્યું છે.\r\n\r\nઉત્તમ પરિણામ પ્રાપ્ત કરનાર બંને વિદ્યાર્થીનીઓ શ્રી વૈષ્ણવ સાધુ માર્ગી વૈરાગી પરિવાર સાથે સંકળાયેલી હોવાથી સમાજમાં પણ આનંદની લાગણી વ્યાપી છે. સફળ વિદ્યાર્થીઓને કોલેજના આચાર્યશ્રી તથા સમગ્ર અધ્યાપક સ્ટાફ દ્વારા હાર્દિક અભિનંદન અને શુભેચ્છાઓ પાઠવવામાં આવી છે.\r\n\r\nસરકારી વિનયન કોલેજ, રાણાવાવ સ્થાપનાવર્ષથી જ સતત શ્રેષ્ઠ પરિણામ આપતી આવી રહી છે અને પોરબંદર પંથકની એકમાત્ર મોડેલ ડિગ્રી કોલેજ તરીકે પોતાની આગવી ઓળખ જાળવી રાખી છે.', '1766338714_6437_1001189931.jpg,1766338714_6051_1001189895.jpg', '2025-12-21 23:08:34'),
(17, 'રાજકોટ સમાધિસ્થ મહંત શ્રી મોહનદાસ બાપુ દુધરેજીયા ના પુણ્યસ્મરણાર્થે તેમના પરિવાર દ્વારા શ્રી મહાવિષ્ણુ મંડપનું ભવ્ય આયોજન સમ્પન્ન થયું', 'રાજકોટ, તા. ૨૧/૧૨/૨૦૨૫\r\nરાજકોટ મુકામે લુહારમંદિર સાથે સંકળાયેલા સ્વ. મહંત શ્રી મોહનદાસ બાપુ દુધરેજીયા ના પુણ્યસ્મરણાર્થે તેમના પરિવાર દ્વારા શ્રી મહાવિષ્ણુ મંડપનું ભવ્ય અને ધાર્મિક ભાવનાથી ભરપૂર આયોજન કરવામાં આવ્યું હતું. આ પવિત્ર પ્રસંગે સંતો, મહંતો તેમજ સમાજના આગેવાનોની મોટી સંખ્યામાં ઉપસ્થિતિ રહી, જેથી સમગ્ર વાતાવરણ ભક્તિ અને આસ્થા થી ઓતપ્રોત બન્યું હતું.\r\nકાર્યક્રમ દરમિયાન વેદમંત્રોચ્ચાર, વિષ્ણુ સહસ્રનામ પાઠ તથા ધાર્મિક વિધિઓનું આયોજન કરવામાં આવ્યું હતું. સંત-મહંતોના આશીર્વચનો દ્વારા સ્વ. મહંત શ્રી મોહનદાસ બાપુના સમાજપ્રતિના યોગદાન, સેવાભાવ અને ધાર્મિક જીવન પર પ્રકાશ પાડવામાં આવ્યો. તેમના જીવનકાળ દરમિયાન કરેલ સમાજસેવા અને આધ્યાત્મિક કાર્યોને યાદ કરી શ્રદ્ધાંજલિ અર્પણ કરવામાં આવી હતી.\r\nઆ સમગ્ર આયોજન દુધરેજીયા પરિવાર દ્વારા ખૂબ જ સુવ્યવસ્થિત, શિસ્તબદ્ધ અને ભાવપૂર્ણ રીતે સંપન્ન થયું હતું. કાર્યક્રમમાં ઉપસ્થિત મહેમાનો માટે સ્વાગત, વ્યવસ્થા અને ભોજન પ્રસાદની ઉત્તમ વ્યવસ્થા કરવામાં આવી હતી, જેને સર્વત્ર પ્રશંસા મળી હતી. સમાજના આગેવાનોએ દુધરેજીયા પરિવારના આ ધાર્મિક આયોજનને અનુસરણિય ગણાવી અભિનંદન પાઠવ્યા હતા.\r\nશ્રી મહાવિષ્ણુ મંડપનું આ આયોજન માત્ર એક ધાર્મિક વિધિ પૂરતું સીમિત ન રહી, પરંતુ સમાજમાં એકતા, શ્રદ્ધા અને સંસ્કારના સંદેશને વધુ મજબૂત બનાવતું સાબિત થયું. સમગ્ર કાર્યક્રમ શાંતિપૂર્ણ અને સફળ રીતે સંપન્ન થયો હતો.\r\nઅહેવાલ : નરેશ દેશાણી, રાણપર', '1766338869_7786_1001189846.jpg,1766338869_6936_1001189849.jpg,1766338869_7175_1001189852.jpg,1766338869_7325_1001189855.jpg,1766338869_4918_1001189858.jpg,1766338869_5482_1001189861.jpg', '2025-12-21 23:11:09'),
(18, 'પ્રાથમિક શિક્ષકથી પીએચ.ડી. સુધી: ડૉ. પુરણદાસ ગોંડલીયાની ગૌરવસભર સિદ્ધિ', 'ગીર સોમનાથ જિલ્લાના મોરૂકા (ગીર) ગામના વતની તથા હાલ સુરતની સરકારી શાળા પાંડુરંગ ખાનખોજે પ્રાથમિક શાળામાં શિક્ષક તરીકે ફરજ બજાવતા ડૉ. પુરણદાસ ગોંડલીયાએ શૈક્ષણિક ક્ષેત્રે નોંધપાત્ર સિદ્ધિ હાંસલ કરી છે.\r\n\r\nતેમણે આર્ટ્સ એન્ડ કોમર્સ કોલેજ, મેંદરડાના પ્રાધ્યાપક ડૉ. ભરત ડોડીયાના માર્ગદર્શન હેઠળ\r\n“ડો. લક્ષ્મીનારાયણ લાલના નાટકોમાં નિરૂપિત સમસ્યાઓના સંદર્ભમાં એક અભ્યાસ” વિષય પર મહાશોધ નિબંધ રજૂ કર્યો હતો. આ સંશોધન કાર્યને ભક્ત કવિ નરસિંહ મહેતા યુનિવર્સિટી દ્વારા માન્યતા આપી તેમને પીએચ.ડી. ની પદવી એનાયત કરવામાં આવી છે.\r\n\r\nપ્રાથમિક શિક્ષક હોવા છતાં ઊંડા સંશોધન, સાહિત્યપ્રેમ અને અવિરત મહેનતના બળે ડૉ. પુરણદાસ ગોંડલીયાએ આ મહત્વપૂર્ણ સફળતા પ્રાપ્ત કરી છે, જે સમગ્ર સમાજ અને શિક્ષક સમુદાય માટે ગૌરવની વાત છે. તેમની આ સિદ્ધિ અન્ય શિક્ષકો અને યુવાનો માટે પ્રેરણારૂપ સાબિત થશે.\r\n\r\nડૉ. પુરણદાસ ગોંડલીયાને પીએચ.ડી. ની પદવી પ્રાપ્ત કરવા બદલ પરિવારજનો, મિત્રવર્તુળ, શૈક્ષણિક જગત તથા સમાજ તરફથી હાર્દિક અભિનંદન અને શુભેચ્છાઓ વ્યક્ત કરવામાં આવી રહી છે. ', '1766544276_1940_1001193097.jpg,1766544276_7426_1001193084.jpg', '2025-12-24 08:14:36'),
(19, 'નિલેશભાઈ કાપડીનું જન્મદિવસે સમાજહિત માટે પ્રશંસનીય યોગદાન', 'નિલેશભાઈ દયારામભાઈ કાપડીના જન્મદિવસ નિમિત્તે એક સુંદર અને પ્રેરણાદાયી સેવાકાર્ય કરવામાં આવ્યું. મૂળ થાનગઢ નિવાસી અને હાલ સુરેન્દ્રનગર ખાતે વસવાટ કરતા નિલેશભાઈએ પોતાના જન્મદિવસની ખુશી સમાજના ભવિષ્ય સમાન વિદ્યાર્થીઓ સાથે વહેંચી, હનુમંત વિદ્યાર્થી ગૃહ, સુરેન્દ્રનગર ખાતે ₹ ૧૧,૦૦૦/- (અગિયાર હજાર રૂપિયા) ની સપ્રેમ ભેટ અર્પણ કરી.\r\n\r\nવિદ્યાર્થીઓના શિક્ષણ, સંસ્કાર અને સર્વાંગી વિકાસ માટે સતત કાર્યરત હનુમંત વિદ્યાર્થી ગૃહના ટ્રસ્ટી તરીકે નિલેશભાઈ કાપડી સમાજસેવામાં મહત્વપૂર્ણ ભૂમિકા ભજવી રહ્યા છે. તેમનું આ સેવાભાવી કાર્ય માત્ર દાન પૂરતું સીમિત નથી, પરંતુ સમાજ પ્રત્યેની તેમની ઊંડી લાગણી અને જવાબદારીનું જીવંત પ્રતિબિંબ છે.\r\n\r\nજન્મદિવસને વ્યક્તિગત ઉજવણીમાંથી બહાર લાવી, તેને સમાજહિતના કાર્ય સાથે જોડવાની તેમની વિચારધારા નિઃસંદેહ પ્રશંસનીય છે. નિલેશભાઈનું આ કાર્ય અન્ય સૌ માટે પ્રેરણારૂપ બનશે અને સમાજમાં સેવા તથા સહકારની ભાવનાને વધુ મજબૂત બનાવશે.\r\n\r\nઈશ્વર તેમને દીર્ઘાયુ, ઉત્તમ આરોગ્ય અને સમાજસેવાના માર્ગે અવિરત આગળ વધવાની શક્તિ પ્રદાન કરે — તેવી હાર્દિક શુભેચ્છાઓ ', '1766759276_7972_1001200040.jpg', '2025-12-26 19:57:56'),
(20, 'શ્રી માર્ગી વૈષ્ણવ સાધુ સમાજ રાજકોટ.સેવા, સંવેદના અને સહકારની સુગંધ ફેલાવતું એક સ્નેહભર્યું કાર્ય', '“બાય બાય નવરાત્રી ૨૦૨૫” સમિતિ દ્વારા આજે સમાજસેવાના ઉત્તમ ઉદાહરણરૂપે એક પ્રશંસનીય કાર્ય સંપન્ન થયું. શ્રી માર્ગી વૈષ્ણવ સાધુ સમાજ, રાજકોટના માર્ગદર્શન હેઠળ જૂનાગઢ સ્થિત શ્રી સીતારામ કન્યા છાત્રાલય ખાતે શુદ્ધ પીવાના પાણી માટે RO વોટર ફિલ્ટર તથા વિદ્યાર્થિનીઓના સર્વાંગી વિકાસ માટે રમતગમતના વિવિધ સાધનો સ્નેહપૂર્વક સહયોગ ભેટરૂપે અર્પણ કરવામાં આવ્યા.\r\n\r\nછાત્રાલયમાં નિવાસ કરતી દીકરીઓના આરોગ્ય, સુખાકારી અને ઉત્સાહભર્યા જીવન માટે આ ભેટો આશીર્વાદ સમાન બની રહી છે. શુદ્ધ પાણી આરોગ્યની આધારશિલા છે, તો રમતગમત જીવનમાં શિસ્ત, આત્મવિશ્વાસ અને આનંદનો સંચાર કરે છે. આ બંને સુવિધાઓ દીકરીઓના ઉજ્જવળ ભવિષ્ય માટે મહત્વપૂર્ણ પગથિયાં છે.\r\n\r\n“બાય બાય નવરાત્રી ૨૦૨૫” સમિતિનો આ સેવાભાવી અભિગમ માત્ર ભેટ પૂરતો નથી, પરંતુ સમાજ પ્રત્યેની જવાબદારી, સંવેદનશીલતા અને માનવતાના મૂલ્યોને ઉજાગર કરે છે. દીકરીઓના ચહેરા પર જોવા મળેલી ખુશી અને આત્મવિશ્વાસ એ જ આ સેવા કાર્યની સાચી સફળતા છે.\r\n\r\nઆવા સેવાકાર્યો સમાજમાં સકારાત્મક વિચારધારાને પ્રેરણા આપે છે અને ભવિષ્યમાં પણ વધુ ને વધુ લોકો સેવાપથ પર આગળ વધે તેવી આશા જગાવે છે. શ્રી માર્ગી વૈષ્ણવ સાધુ સમાજ રાજકોટ તથા “બાય બાય નવરાત્રી ૨૦૨૫” સમિતિના આ ઉત્તમ કાર્યને હૃદયપૂર્વક અભિનંદન.', '1766834658_9999_1001202680.jpg', '2025-12-27 16:54:18'),
(21, 'વિદ્યાર્થીઓના ભવિષ્ય માટે સ્નેહભર્યો સહારો – દીપકકુમાર જીવરામદાસ વૈષ્ણવ', 'મૂળ ધ્રાંગધ્રા, જિલ્લા સુરેન્દ્રનગરના સેવાભાવી વ્યક્તિત્વ શ્રી દીપકકુમાર જીવરામદાસ વૈષ્ણવ દ્વારા હનુમંત વિદ્યાર્થી ગૃહ ખાતે કરવામાં આવેલ ત્રણ મહિના માટેની સીધો સામાન સપ્રેમ ભેટ માત્ર દાન , આ એક દાન જ નથી પરંતુ અનેક વિદ્યાર્થીઓના સપનાઓને જીવંત રાખતી એક સંવેદનશીલ લાગણી છે.\r\n\r\nઆ અનન્ય સહયોગ દ્વારા વિદ્યાર્થી ગૃહમાં નિવાસ કરતા વિદ્યાર્થીઓને માત્ર ભોજન કે સુવિધા જ નથી મળતી, પરંતુ તેમને એવું અનુભવ થાય છે કે સમાજ તેમની સાથે ઊભો છે. જ્યારે કોઈ અજાણ્યો હાથ આગળ આવીને સહારો આપે છે, ત્યારે વિદ્યાર્થીના મનમાં આત્મવિશ્વાસ જન્મે છે અને જીવનમાં આગળ વધવાની શક્તિ મળે છે.\r\n\r\nશ્રી દીપકકુમાર વૈષ્ણવનો આ સેવાભાવ નિઃસ્વાર્થ છે,  અને અત્યંત પ્રેરણાદાયક છે. આવા કાર્યો સમાજમાં માનવતા, કરુણા અને સહકારની ભાવનાને જીવંત રાખે છે. હનુમંત વિદ્યાર્થી ગૃહના દરેક વિદ્યાર્થી માટે આ ત્રણ મહિના માત્ર સમયગાળો નહીં, પરંતુ આશા, હિંમત અને આશીર્વાદ સમાન બની રહેશે.\r\n\r\nહનુમંત વિદ્યાર્થી ગૃહ પરિવાર તથા સમગ્ર સમાજ તરફથી શ્રી દીપકકુમાર વૈષ્ણવને તેમના આ ઉદાર અને હૃદયથી ભરેલા સહયોગ માટે વંદન અને આભાર વ્યક્ત કરવામાં આવે છે. તેમની આ સ્નેહભરી સેવા અનેક લોકોને પ્રેરણા આપતી રહે એવી શુભેચ્છા.', '1766834809_1122_1001202661.jpg', '2025-12-27 16:56:49'),
(22, 'વૈષ્ણવ સાધુ સમાજના ગૌરવ જયેશભાઈ જી દાણીધારિયાને રાજકોટ ફાયર ડિપાર્ટમેન્ટમાં સબ ફાયર ઓફિસર તરીકે પ્રમોશન', 'રાજકોટ ફાયર ડિપાર્ટમેન્ટમાં ફરજ બજાવતા વૈષ્ણવ સાધુ સમાજના ગૌરવ અને યુવા અધિકારી શ્રી જયેશભાઈ જી દાણીધારિયાને તેમની નિષ્ઠાપૂર્ણ સેવા, શિસ્તબદ્ધ કાર્યશૈલી અને ઉત્તમ કામગીરીના પરિણામે સબ ફાયર ઓફિસર તરીકે પ્રમોશન મળ્યું છે.\r\n\r\nફાયર ડિપાર્ટમેન્ટ જેવી જોખમી અને જવાબદારીસભર સેવા ક્ષેત્રમાં સતત સમર્પણ, તત્પરતા અને માનવસેવાના ભાવ સાથે ફરજ નિભાવનાર જયેશભાઈએ સમાજ તથા વિભાગ બંનેનું નામ ગૌરવપૂર્વક ઉજાગર કર્યું છે. તેમનો આ પ્રમોશન યુવા પેઢી માટે પ્રેરણાસ્રોત બન્યો છે.\r\n\r\nઆ સિદ્ધિ બદલ વૈષ્ણવ સાધુ સમાજમાં આનંદની લાગણી વ્યાપી છે. સમાજના આગેવાનો, મિત્રો અને સહકર્મીઓએ તેમને દિલથી અભિનંદન પાઠવી ઉજ્જવળ ભવિષ્ય માટે શુભકામનાઓ વ્યક્ત કરી છે.\r\n\r\nશુભેચ્છક:\r\nશ્રી હરેશ એચ. ગોંડલીયા\r\nફાયર ડિપાર્ટમેન્ટ, રાજકોટ\r\n\r\nજયેશભાઈની આ સફળતા તેમના પરિવાર, સમાજ અને રાજકોટ ફાયર ડિપાર્ટમેન્ટ માટે ગૌરવનો વિષય બની છે.', '1767064586_9091_1001208797.jpg', '2025-12-30 08:46:26'),
(23, 'આપણા પોરબંદર જિલ્લાના વૈષ્ણવ સમાજ સરસ્વતી સન્માન સમારોહ તથા સ્નેહમિલન ૨૦૨૬ નું ભવ્ય આયોજન ', 'પોરબંદર જિલ્લા વૈષ્ણવ સાધુ સમાજ દ્વારા \r\n“સરસ્વતી સન્માન સમારોહ તથા સ્નેહમિલન – ૨૦૨૬” નું ભવ્ય આયોજન\r\n\r\nપોરબંદર : પોરબંદર જિલ્લાના વૈષ્ણવ સાધુ સમાજ માટે ગૌરવ, એકતા અને સંસ્કૃતિને ઉજાગર કરતી એક ઐતિહાસિક ક્ષણ આવવા જઈ રહી છે. સમાજના તેજસ્વી તારાલાઓના સન્માન તથા પરસ્પર સ્નેહ, સૌહાર્દ અને સંઘભાવનાને વધુ દ્રઢ બનાવવા માટે “સરસ્વતી સન્માન સમારોહ તથા સ્નેહમિલન – ૨૦૨૬” નો ભવ્ય કાર્યક્રમ તા. ૧૧/૦૧/૨૦૨૬ (રવિવાર) ના રોજ આયોજિત થવાનો છે.\r\n\r\nઆ કાર્યક્રમ માત્ર એક સન્માન સમારોહ નથી, પરંતુ વૈષ્ણવ સાધુ  સમાજની ઓળખ, તેની સંસ્કૃતિ અને એકતાનો ઉત્સવ છે. વર્ષોથી સમાજે જાળવી રાખેલી પરંપરા, મૂલ્યો અને સામૂહિક ભાવનાને નવી ઊર્જા આપવાનો આ અનોખો અવસર છે. સમાજના દરેક વર્ગ, દરેક પરિવારને એક જ મંચ પર એકત્ર લાવવાનો આ પ્રયાસ વૈષ્ણવ સાધુ સમાજની એકતા માટે માઈલસ્ટોન સાબિત થશે.\r\n\r\nઆયોજન સમિતિ દ્વારા આગામી દિવસોમાં કાર્યક્રમ અંગેની સંપૂર્ણ વિગતો આમંત્રણ સંદેશા, ટેલિફોનિક સંપર્ક તેમજ રૂબરૂ મુલાકાત જેવા વિવિધ માધ્યમોથી સમાજના દરેક પરિવાર સુધી સ્નેહપૂર્વક પહોંચાડવામાં આવશે. સમિતિએ સ્પષ્ટ કર્યું છે કે આ કાર્યક્રમ માટે સમાજ પાસેથી એક જ ભાવપૂર્ણ વિનંતી છે કે દરેક પરિવાર બીજા એક પરિવાર સાથે પધારે અને પોરબંદર જિલ્લામાં વસતા વૈષ્ણવ સમાજના દરેક પરિવારને આ સ્નેહમિલનમાં જોડાવા પ્રેરણા આપે.\r\n\r\nઆ જવાબદારી સ્વીકારનાર દરેક વ્યક્તિ આપોઆપ આ આયોજન સમિતિનો અભિન્ન હિસ્સો બની જશે. દરેકની હાજરીથી સમાજની એકતા વધુ મજબૂત બનશે અને આ સ્નેહમિલન કાર્યક્રમ ખરેખર અર્થસભર અને સ્મરણિય બની રહેશે.\r\n\r\n ખાસ સંકલ્પ\r\n\r\nઆ અવસરે આયોજન સમિતિ દ્વારા સમાજના સૌને એક સંકલ્પ લેવા આહ્વાન કરવામાં આવ્યું છે.\r\n“દરેક પરિવાર એક બીજા પરિવારને પોતાની સાથે લઈને આવશે.”\r\nઆટલી જ સ્નેહસભર અપેક્ષા સાથે આ કાર્યક્રમને સમાજનું સંયુક્ત ઉત્સવ બનાવવાની અપીલ કરવામાં આવી છે.\r\n\r\n“ભેગા થવું એ સફળતા છે, ભેગા રહેવું એ પ્રગતિ છે, પરંતુ ભેગા મળી કામ કરવું એ સૌથી મોટી સફળતા છે.”\r\n\r\nઆવો, સૌ પરિવાર સાથે જોડાઈને પોરબંદર જિલ્લા વૈષ્ણવ સમાજના આ ઐતિહાસિક સ્નેહમિલનને યાદગાર બનાવીએ — તેમ આયોજન સમિતિ દ્વારા પોરબંદર વૈષ્ણવ  સાધુ સમાજ પરિવારના સૌને ભાવભર્યું આમંત્રણ પાઠવવામાં આવ્યું છે.', '1767080254_9737_1001210479.jpg', '2025-12-30 13:07:34'),
(24, 'શ્રી સ્વામિનારાયણ ગુરુકુળની ભૂતપૂર્વ વિદ્યાર્થીની પ્રિયાંશી સરપદડિયાની ઐતિહાસિક સિદ્ધિ ધોરણ–૧૨ સાયન્સ (GSEB)માં ૯૪.૪૧ PR સાથે ‘A2’ ગ્રેડ', '“સિદ્ધિ તેને જઈ વરે, જે પરસેવે ન્હાય” – આ કહેવતને સાકાર કરતી એક ગૌરવભરી સિદ્ધિ તરીકે, અત્યંત હર્ષ અને ગર્વની લાગણી સાથે જાહેર કરવામાં આવે છે કે શ્રી સ્વામિનારાયણ ગુરુકુળની ભૂતપૂર્વ વિદ્યાર્થીની કુમારી સરપદડિયા પ્રિયાંશી મનોજભાઈએ વર્ષ ૨૦૨૪–૨૫ની ધોરણ–૧૨ સાયન્સ (GSEB) બોર્ડ પરીક્ષામાં ૯૪.૪૧ PR સાથે ‘A2’ ગ્રેડ મેળવી સંસ્થાના શૈક્ષણિક ઇતિહાસમાં એક સુવર્ણ સોપાન સર કર્યું છે.\r\n\r\nઆ અસાધારણ સફળતા પ્રિયાંશીબેનના અથાક પરિશ્રમ, અડગ નિશ્ચય અને વિદ્યા પ્રત્યેના અખૂટ સમર્પણનું જીવંત પ્રતિબિંબ છે. ગુરુકુળમાં અભ્યાસકાળ દરમિયાન તેમણે કેળવેલી શિસ્તબદ્ધ જીવનશૈલી, નૈતિક મૂલ્યો અને આધ્યાત્મિક સંસ્કારો તેમની આ ઉજ્જવળ સિદ્ધિમાં સ્પષ્ટપણે ઝળહળી ઊઠે છે.\r\n\r\nપ્રિયાંશીબેને માત્ર ઉત્તમ ટકાવારી હાંસલ કરી નથી, પરંતુ પોતાની મેધાશક્તિ અને જ્ઞાનબળ દ્વારા શ્રી સ્વામિનારાયણ ગુરુકુળની ગરિમાને સમાજમાં ગૌરવપૂર્વક ઉજાગર કરી છે. તેમની આ ઐતિહાસિક સફળતા વર્તમાન વિદ્યાર્થીઓ માટે પ્રેરણાસ્રોત અને ભાવિ પેઢી માટે અનુસરણયોગ્ય આદર્શ બની રહેશે.\r\n\r\nઆ ભવ્ય સિદ્ધિ બદલ સંસ્થા પ્રિયાંશીબેનને હાર્દિક અભિનંદન અને સરાહના પાઠવે છે તથા તેઓ પ્રગતિના પંથે સદૈવ અગ્રેસર રહી રાષ્ટ્ર અને સમાજનું ગૌરવ વધારતા રહે તેવી અભ્યર્થના કરે છે.\r\nશ્રી સ્વામિનારાયણ ભગવાનના અનંત આશીર્વાદ સાથે પ્રિયાંશીબેનના ઉજ્જવળ, સફળ, સંસ્કારસભર અને સમાજોપયોગી ભવિષ્ય માટે હાર્દિક શુભકામનાઓ', '1767602467_9606_1001228178.jpg,1767602467_3947_1001228177.jpg', '2026-01-05 14:11:07'),
(25, 'તાલાલા શહેરમાં માનવતાનો અનોખો મહોત્સવ – સમૂહ લગ્ન દ્વારા સમાજસેવા', '\r\nતાલાલા શહેરમાં યોજાવા જઈ રહેલા સમૂહ લગ્ન માત્ર એક લગ્ન સમારોહ નથી, પરંતુ તે સમાજ પ્રત્યેની જવાબદારી, સંવેદના અને યુવા શક્તિની જીવંત પ્રતિબિંબ છે. આજના સમયમાં જ્યાં ખર્ચાળ લગ્નની દોડ ચાલી રહી છે, ત્યાં તાલાલાના યુવાઓએ સરળતા, સમાનતા અને સેવા ભાવનાનો અદભૂત દાખલો રજૂ કર્યો છે.\r\n\r\nઆ સમૂહ લગ્નમાં જોડાનારા નવદંપતિઓને કરિયાવર રૂપે ફ્રીઝ, વોશિંગ મશીન તેમજ કલર ટીવી જેવા જરૂરી ઘરગથ્થુ સાધનો દાન સ્વરૂપે આપવામાં આવી રહ્યા છે. આ માત્ર વસ્તુઓનું દાન નથી, પરંતુ નવજીવનની શરૂઆત માટે આશીર્વાદ સમાન સહારો છે. આવા કરિયાવરથી નવદંપતિઓના જીવનમાં સુખ, સગવડ અને આત્મવિશ્વાસનો પાયો મજબૂત બને છે.\r\n\r\nખાસ નોંધપાત્ર વાત એ છે કે આ સમગ્ર આયોજનમાં યુવાઓની આગવી ભૂમિકા છે. પોતાની શક્તિ, સમય અને વિચારધારા સમાજહિતમાં અર્પણ કરી યુવાઓએ સાબિત કર્યું છે કે સાચો વિકાસ ભવ્યતા માં નહીં, પરંતુ માનવતા અને સહકારમાં છે. આ કાર્યથી સમાજમાં સમાનતાનો સંદેશ ફેલાય છે અને જરૂરિયાતમંદ પરિવારોને માન સાથે જીવન શરૂ કરવાની તક મળે છે.\r\n\r\nતાલાલા શહેરનું આ સમૂહ લગ્ન આયોજન ખરેખર પ્રશંસનીય, અનુસરણિય અને પ્રેરણાદાયક છે. આવા સેવાકાર્યો સમાજને નવી દિશા આપે છે અને આવતી પેઢી માટે ઉત્તમ સંસ્કાર છોડી જાય છે. તાલાલાના યુવાઓને આ માનવતાભર્યા કાર્ય માટે હૃદયપૂર્વક અભિનંદન અને શુભકામનાઓ.', '1768102665_6035_1001238357.jpg,1768102665_7530_1001233526.jpg', '2026-01-11 09:07:45'),
(26, 'પોરબંદર ખાતે સરસ્વતી સન્માન સમારોહ સ્નેહમિલન-૨૦૨૬ યોજાય ગયો', 'અહેવાલ:સાગરભાઈ રામકબીર અડવાણા.\r\nપોરબંદર જિલ્લાના શ્રી વૈષ્ણવ સાધુ (બા. વૈ.) સમાજ દ્વારા વર્ષ–૨૦૨૬ના ઉપક્રમે સમાજની એકતા, સંસ્કાર અને શિક્ષણપ્રત્યેની પ્રતિબદ્ધતાને ઉજાગર કરતો સ્નેહમિલન તથા સરસ્વતી સન્માન સમારોહ શ્રી સોરઠીયા ધોબી સમાજની વાડી, બિરલા હૉલ રોડ, પોરબંદર ખાતે ભવ્ય રીતે સંપન્ન થયો.\r\nસમાજના વ્હાલા દીકરીઓ અને દીકરાઓની શૈક્ષણિક સિદ્ધિઓને પ્રોત્સાહન આપવા તથા તેમની કારકિર્દીને નવી દિશા આપવા હેતુસર આયોજિત આ સમારોહમાં વિદ્યાર્થીઓને પ્રોત્સાહનરૂપે સ્મૃતિચિહ્ન (શિલ્ડ) આપી \r\nસન્માનિત કરવામાં આવ્યા. સાથે સાથે સમાજના વરિષ્ઠ નાગરિકોનું પણ આદરપૂર્વક બહુમાન કરવામાં આવ્યું,\r\n\r\nજે સમાજની સંસ્કારસભર પરંપરાનું ઉત્તમ ઉદાહરણ બન્યું.કાર્યક્રમને વધુ સૌહાર્દપૂર્ણ બનાવવા બહેનો અને દીકરીઓ દ્વારા પારંપરિક ગરબા રજૂ કરવામાં આવ્યા તેમજ સ્વરુચિ ભોજનની વ્યવસ્થા કરવામાં આવી. સમગ્ર સમારોહમાં પોરબંદર જિલ્લાના વૈષ્ણવ સાધુ સમાજના પરિવારજનો મોટી સંખ્યામાં ઉપસ્થિત રહીને કાર્યક્રમને સફળ બનાવ્યો.\r\nઆ સમગ્ર કાર્યક્રમનું આયોજન શ્રી વૈષ્ણવ સાધુ (બા. વૈ.) સમાજ – પોરબંદર આયોજન સમિતિ દ્વારા કરવામાં આવ્યું હતું. સમાજના એકતા, શિક્ષણ અને સંસ્કૃતિના મૂલ્યોને પ્રગટ કરતો આ સમારોહ સૌ માટે યાદગાર બની રહ્યો.', '1768191631_7674_1001240226.jpg,1768191631_8010_1001240238.jpg', '2026-01-12 00:00:00'),
(27, 'શિયાળામાં સેવાનું આવરણ: માનસબાગ વિદ્યાર્થી ભવન અને સીતારામ કન્યા છાત્રાલય જૂનાગઢ માનવ મંદિર સાવરકુંડલા દ્વારા ધાબળા વિતરણ', 'તારીખ:૧૩/૦૧/૨૦૨૬ આજરોજ માનવ મંદિર (સાવરકુંડલા)પરમ પૂજ્ય શ્રી પાવન કરકમળે ભક્તિરામબાપુજીના સેવાભાવથી ભરપૂર કાર્યક્રમ યોજાયો. આ કાર્યક્રમ અંતર્ગત જૂનાગઢ શહેર ખાતે આવેલ કન્યા છાત્રાલય તેમજ માનસ બાગ વિદ્યાર્થી ભવનમાં અભ્યાસ કરતા વિદ્યાર્થીઓને ઠંડીની કઠોર સિઝનમાં ઉપયોગી થાય તે હેતુસર ધાબળાનું વિતરણ કરવામાં આવ્યું.\r\n\r\nપરમ પૂજ્ય બાપુજીએ વિદ્યાર્થીઓને આશીર્વચન આપતાં જણાવ્યું કે શિક્ષણ સાથે સંસ્કાર અને સંવેદના જોડાય ત્યારે જ સમાજની સાચી ઉન્નતિ શક્ય બને છે. દીકરીઓ તથા વિદ્યાર્થીઓ દેશનું ભવિષ્ય છે; તેમના આરોગ્ય, સુરક્ષા અને સુખાકારી માટે કરવામાં આવતી દરેક સેવા માનવ સેવા સમાન છે. શિયાળાની ઋતુમાં ધાબળા જેવી આવશ્યક સહાય માત્ર શારીરિક ઉષ્મા જ નથી આપતી, પરંતુ સેવાભાવની અનુભૂતિ દ્વારા માનસિક હિંમત અને આત્મવિશ્વાસ પણ વધારે છે.\r\n\r\nઆ પ્રસંગે કન્યા છાત્રાલય અને માનસ બાગ વિદ્યાર્થી ભવનના સંચાલકો દ્વારા માનવ મંદિર તથા પરમ પૂજ્ય શ્રી ભક્તિરામબાપુજી પ્રત્યે હૃદયપૂર્વક આભાર વ્યક્ત કરવામાં આવ્યો. તેમણે જણાવ્યું કે આવા સેવાકાર્યોના કારણે વિદ્યાર્થીઓ નિશ્ચિંત મનથી પોતાનો અભ્યાસ આગળ વધારી શકે છે અને જીવનમાં સકારાત્મક દૃષ્ટિકોણ વિકસાવે છે.\r\n\r\nધાબળા વિતરણ દરમિયાન સમગ્ર વાતાવરણ કરુણા, સંવેદના અને આત્મીયતાથી પરિપૂર્ણ હતું. વિદ્યાર્થીઓના ચહેરા પર દેખાતી ખુશી અને સંતોષ આ સેવાકાર્યની સફળતાનું જીવંત પ્રતિબિંબ હતું. માનવ મંદિરની સેવાભાવી પરંપરા અને પરમ પૂજ્ય બાપુજીનો સમાજ પ્રત્યેનો અખૂટ પ્રેમ આ પ્રસંગે સ્પષ્ટ રીતે અનુભવી શકાયો.\r\n\r\nઆવા સેવાકાર્યો સમાજમાં માનવતા, સહકાર અને સેવાના સંસ્કારને મજબૂત કરે છે તથા આવનારી પેઢીને સેવા માર્ગે આગળ વધવા પ્રેરણા આપે છે.', '1768235530_2993_1001242871.jpg,1768235530_2523_1001242870.jpg,1768235530_8656_1001242869.jpg,1768235530_9585_1001242867.jpg,1768235530_7080_1001242866.jpg,1768235530_8011_1001242865.jpg,1768235530_5325_1001242868.jpg,1768235530_7782_1001242864.jpg,1768235530_5840_1001242961.jpg,1768235530_6913_1001242967.jpg,1768235530_9407_1001242964.jpg,1768235530_5435_1001243038.jpg,1768235530_1921_1001243037.jpg,1768235530_8416_1001242958.jpg', '2026-01-12 22:02:10'),
(28, 'સમાજસેવા અને સંસ્કારનો સંગમ : તાલાલા ગીરમાં ભવ્ય સમૂહલગ્નોત્સવ', 'શ્રી મારૂતીનંદન વૈષ્ણવ માર્ગી યુવા સાધુ સમાજ, તાલાલા ગીર દ્વારા તા. ૧૮/૦૧/૨૦૨૬ ના રોજ એક ભવ્ય અને સ્મરણિય સમૂહલગ્નોત્સવનું આયોજન કરવામાં આવ્યું હતું. સમાજની દીકરીઓના સુખી અને સન્માનજનક વૈવાહિક જીવન માટે યોજાયેલ આ સમૂહલગ્નોત્સવ માનવતા, સંસ્કાર અને સહકારનું ઉત્તમ ઉદાહરણ બની રહ્યો.આ પાવન પ્રસંગે સમાજના ગૌરવ સમાન અનેક મહાનુભાવો, સંતો, મહંતો તથા રાજકીય અને સામાજિક આગેવાનોની ઉપસ્થિતિએ કાર્યક્રમની શોભા વધારી હતી.\r\nકાર્યક્રમમાં પૂજ્ય ભક્તિરામબાપુ (માનવ મંદિર, સાવરકુંડલા),શ્રી રાજેશભાઈ ચુડાસમા – સાંસદ સભ્યશ્રી, જુનાગઢ તથા ઉપાધ્યક્ષ ગુજરાત ભાજપ સંગઠન,શ્રી માનસિંહભાઈ પરમાર – પ્રમુખશ્રી OBC મોરચો, ગુજરાત ભાજપ સંગઠન,\r\nપૂજ્ય મહંતશ્રી એન્ડીબાપુ (બાથેશ્વર ધામ, માણેકવાડા),\r\nપૂજ્ય મહંતશ્રી કિશોરબાપુ (ગરણી ધામ)\r\n\r\nસહીત અનેક સંતો, મહંતો તથા આગેવાનોની હાજરી રહી.\r\nઆ સમૂહલગ્નોત્સવની સૌથી વિશેષ અને પ્રશંસનીય બાબત હતી દીકરીઓને આપવામાં આવેલું સમૃદ્ધ અને સન્માનજનક કરિયાવર. દીકરીઓને કરિયાવર પેટે\r\nફર્નિચર,\r\nગોદરેજ ફ્રીઝ,\r\n32\" સ્માર્ટ ટીવી,\r\nવોશિંગ મશીન,\r\nસોનાના ચીપવાળા પાટલા,\r\nસોનાનો દાણો\r\nસહીત ૧૨૦થી વધુ ઉપયોગી વસ્તુઓ આપવામાં આવી, જે તેમની નવી જિંદગીની મજબૂત શરૂઆત માટે આધારરૂપ બનશે.આ સમૂહલગ્નોત્સવ માત્ર લગ્નવિધિ પૂરતો સીમિત ન રહી, પરંતુ સમાજમાં સમાનતા, સહકાર, દીકરી સન્માન અને સામૂહિક જવાબદારીનો મજબૂત સંદેશ આપતો કાર્યક્રમ સાબિત થયો. યુવા સાધુ સમાજ દ્વારા કરવામાં આવેલું આ આયોજન સમાજ માટે પ્રેરણાદાયક ઉદાહરણ બની રહેશે.આવા સેવાભાવી કાર્યો દ્વારા સમાજમાં એકતા, સંસ્કાર અને માનવતા સતત ફૂલતી રહે  એ જ આ સમૂહલગ્નોત્સવનો સચોટ સંદેશ છે.', '1768812332_8277_1001260261.jpg,1768812332_7442_1001260256.jpg,1768812332_8144_1001260273.jpg,1768812332_5078_1001260270.jpg', '2026-01-19 14:15:32'),
(29, 'ખાંભા હરિયાણીની પુત્રી એ સાધુ સમાજને ગૌરવ અપાવ્યું', 'ખાંભા સાધુ સમાજ માટે અતિ ગૌરવની ક્ષણ સર્જાઈ છે. ખાંભા સાધુ સમાજના અગ્રણી અને નિવૃત આચાર્ય શ્રી નાગરભાઈ હરિયાણીની પુર્ગા, તથા રાજકોટના ગોંડલીયા પરિવારની વહુ ** કિરણબેન ગોંડલીયા (હરિયાણી)**એ પોતાની પ્રતિભા અને સાધનાથી સમગ્ર સાધુ સમાજનું માન વધાર્યું છે.\r\n\r\nનાનપણથી જ સ્વરસાધનામાં લીન રહેલી કિરણબેને સંગીત પ્રત્યેની અખૂટ લગન અને શ્રદ્ધાથી આજે ખૂબ જ ટૂંકા સમયમાં એક પ્રતિભાશાળી ગાયિકા તરીકે વિશિષ્ટ ઓળખ ઊભી કરી છે. હાલ તેઓ ગુજરાતભરમાં નામી કલાકારો સાથે તેમજ અનેક સાધુ-સંતોની પાવન ઉપસ્થિતિમાં સંતવાણી, પ્રાચીન ભજનો, લોકડાયરા અને લગ્નગીતો દ્વારા શ્રોતાઓના હૃદય જીતી રહી છે.\r\n\r\nઆ જ શ્રેણીમાં સુરત મુકામે વૈષ્ણવ સાધુ સમાજના રામવાડી એકતા મંચ દ્વારા આયોજિત \"લક્ષ્મી વિવાહ વંદના\" જેવા ભવ્ય અને દિવ્ય કાર્યક્રમમાં, અનેક સાધુ-સંતો તથા જ્ઞાતિજનોની ઉપસ્થિતિમાં **કિરણબેન ગોંડલીયા (હરિયાણી)**નું ભવ્ય સન્માન કરવામાં આવ્યું. આ પ્રસંગે કિરણબેને મંચ પર રામ સ્તુતિ ગાઈને સમગ્ર વાતાવરણને ભક્તિમય બનાવી દીધું.\r\n\r\nઆ સન્માન માત્ર વ્યક્તિગત સિદ્ધિ નથી, પરંતુ સમગ્ર ખાંભા સાધુ સમાજ માટે ગૌરવની બાબત છે. આ પળને, આ સન્માનને અમો સૌ હૃદયપૂર્વક બિરદાવીએ છીએ અને ગૌરવની લાગણી અનુભવીએ છીએ.\r\n\r\nખાંભાની દીકરી કિરણબેનને ખાંભા શહેર તથા તાલુકા સાધુ સમાજ તરફથી આશીર્વાદ સાથે હાર્દિક શુભેચ્છાઓ પાઠવવામાં આવે છે. ઈશ્વર તેમને આવનારા સમયમાં પણ આવું જ યશ, માન અને સફળતા આપે એવી સૌની શુભકામનાઓ.', '1768840495_5056_1001260950.jpg,1768840495_5888_1001260949.jpg,1768840495_4645_1001260952.jpg,1768840495_5149_1001260948.jpg', '2026-01-19 22:04:55'),
(30, 'મહાસાધકનું મહાપર્વ : સમાધિ પણ જ્યાં ઉત્સવ બની જાય…', 'જેનાં જીવનનું ધ્યેય જ પરમાત્મા હોય,\r\nજેનાં પ્રાણોમાં સેવા અને સાધનાનો સુગંધ હોય,\r\nએવો સાધુ શરીર ત્યાગે ત્યારે મૃત્યુ પણ ઉત્સવ બની જાય છે…લોએજ ગામ નિવાસી, સમાધિસ્થ પરમ પૂજ્ય સાધુશ્રી પ્રવિણબાપુ તા. ૨૭ જાન્યુઆરી ૨૦૨૫, સોમવારના રોજ રામચરણ પામ્યા. સાધના, સાદગી અને સેવાભાવથી ભરેલું તેમનું જીવન આજે પણ અનેક હૃદયોમાં પ્રેરણારૂપ બની રહ્યું છે.\r\n\r\nઆ મહાન સાધુના સ્મૃતિરૂપે તથા તેમની સાધનાને શ્રદ્ધાંજલિ અર્પણ કરવા માટે સમાધિ ઉત્સવ અને સંત ભંડારાનું ભવ્ય આયોજન આગામી\r\nતા. ૧ ફેબ્રુઆરી ૨૦૨૬, રવિવારના રોજ બપોરે ૩:૦૦ કલાકે.સ્થળ : શ્રીમતી વી.એમ. ચાંડેરા કોલેજ, લોએજ ખાતે યોજાશે.\r\nઆ પાવન પ્રસંગને વિશેષ મહિમા આપવા માટે દેશભરના અનેક પ્રતિષ્ઠિત, સંતશિરોમણી અને મહંતો ઉપસ્થિત રહેશે. જેમાં મુખ્યત્વે \r\nપરમ પૂજ્ય વિશ્વ વંદનીય સંતશ્રી મોરારીબાપુ (તલગાજરડા)\r\nરાષ્ટ્રીય ઉપાધ્યક્ષ શ્રી પંચ દશનામ જુના અખાડાના પૂ. ઈન્દ્રભારતીબાપુ (ભવનાથ, જુનાગઢ )\r\n(માનવ મંદિર)સાવરકુંડલા થી પૂ. ભક્તિરામબાપુ\r\nપુરાણ પ્રવક્તા ડો. મહાદેવપ્રસાદજી મહેતા\r\nશ્રીશ્રી મહામંડલેશ્વર ૧૦૦૮ પરમ પૂજ્ય અજયબાપુ (સવરામંડપ, જુનાગઢ)\r\nરામદેવજી રામાયણ કથાકાર પૂ. કલ્યાણદાસ બાપુ (મેંદરડા)\r\nમામાદેવ મંદિરના મહંત શ્રી ચંદુબાપુ\r\nશ્રીશ્રી મહામંડલેશ્વર ૧૦૦૮ પરમ પૂજ્ય હરકિશનબાપુ (મેસવાણ)\r\nપરમ પૂજ્ય શ્રીશ્રી રૂદ્રભારતીજી બાપુ (સનાતન ખોડલધામ ભારતી આશ્રમ, નિલવાડા)\r\nસહિત અનેક સંતો, મહંતો, રાજસ્વી નેતાઓ અને સેવકવૃંદની વિશાળ ઉપસ્થિતિ રહેશે.\r\nકાર્યક્રમ ક્રમ:\r\nબપોરે ૩:૦૦ કલાકે :સંતસભા\r\nત્યારબાદ : સંતમિલન\r\nસાંજે : સંતભોજન (સંત ભંડારો)\r\n\r\nઆ પ્રસંગે વિશેષ ગૌરવરૂપે, સાવરકુંડલાના સેંજળ-૫ ગામથી પરમ પૂજ્ય મોરારીબાપુ હેલિકોપ્ટર દ્વારા લોએજ પધારશે અને અધ્યક્ષ સ્થાનને શોભાવશે જે લોએજ ગામ માટે ગૌરવની ક્ષણ રહેશે.આ સંતમિલન, સંતસભા અને સંતભોજનના ત્રિવિધ પાવન ઉત્સવમાં\r\nરવિભાઈ પ્રવિણરામ ગોંડલિયા,\r\nગોંડલિયા પરિવાર તથા લોએજ ગામ વતી\r\nસમસ્ત સાધુસંતો, ભાવિક ભક્તો અને સમાજજનોને હૃદયપૂર્વકનું ભાવભર્યું નિમંત્રણ પાઠવવામાં આવે છે.\r\nઆવો… સાધુસેવા, સંતસંગ અને સંસ્કારના આ મહોત્સવના સાક્ષી બનીએ.\r\n', '1768928431_7290_1001264196.png', '2026-01-20 22:30:31'),
(31, 'સન્માનાર્થે આભાર નિવેદન', 'સુરત મુકામે વૈષ્ણવ સાધુ સમાજ રામવાડી યુવા એકતા મંચ દ્વારા આયોજિત\r\n“લક્ષ્મી વિવાહ વંદના – પ્રથમ સમૂહ લગ્નોત્સવ”\r\nઆપણા વૈષ્ણવ સાધુ સમાજના ઇતિહાસમાં એક પાવન, ગૌરવમય તથા ચિરંજીવી સ્મૃતિરૂપ અધ્યાય તરીકે અંકિત થનાર મહાન અનુષ્ઠાન બન્યો છે.\r\n\r\nસમાજની સનાતન પરંપરા, સંસ્કાર અને સેવાભાવનું જીવંત પ્રતિબિંબ એવા આ દિવ્ય આયોજનમાં આપણા વૈષ્ણવ સાધુ સમાજના પૂજ્ય સંતો, મહંતો તેમજ પ્રતિષ્ઠિત અગ્રણીજનોની આશીર્વાદસભર અને તેજસ્વી ઉપસ્થિતિએ સમગ્ર ઉત્સવને અલૌકિક મહિમા અને આત્મીયતા પ્રદાન કરી. આ પ્રસંગ માત્ર વૈવાહિક સંયોગોનો ન રહી, પરંતુ સમાજની એકતા, સંસ્કૃતિ અને સમર્પણભાવનો મહોત્સવ બની રહ્યો.\r\n\r\nઆ પાવન અવસરે સુરત આયોજક સમિતિ દ્વારા અમારા પુત્રવધુ કિરણ ગોંડલીયા\r\nને ગાયક કલાકાર તરીકે જે સન્માન અર્પિત કરવામાં આવ્યું, તે ક્ષણ અમારે માટે અતિ ગૌરવમય, ભાવવિભોર અને અવિસ્મરણીય બની રહી. યુવા પ્રતિભાને પ્રાપ્ત થયેલું આ સન્માન માત્ર એક વ્યક્તિનું સન્માન ન રહી, પરંતુ સમગ્ર વૈષ્ણવ સાધુ સમાજની સાંસ્કૃતિક ચેતના, કલાત્મક પરંપરા અને સંસ્કારમય વારસાની પ્રતિષ્ઠા છે.\r\n\r\nઆ સન્માન દ્વારા અમો માત્ર આનંદિત જ નથી થયા, પરંતુ સમાજ પ્રત્યે વધુ વિનમ્રતા, જવાબદારી અને સમર્પણભાવથી નમન કરી રહ્યા છીએ. આવા પ્રસંગો સમાજના યુવાનોને સન્માર્ગે પ્રેરણા આપે છે તથા સંસ્કારોથી સમૃદ્ધ ભવિષ્યના નિર્માણમાં પ્રેરક બની રહે છે.\r\n\r\nહું,માધવદાસ ગોંડલીયા રે. ડાભાળી\r\n(હાલ રાજકોટ નિવાસી)\r\nઆ પાવન અવસરે સુરત સમૂહ લગ્ન સમિતિના તમામ માનનીય પદાધિકારી શ્રીમંતોનો, સમગ્ર વૈષ્ણવ સાધુ સમાજ ગુજરાતનો તથા સમાજસેવા અને સંસ્કૃતિના સંવર્ધનમાં અવિરત સમર્પિત સાધુવંદના ડિજિટલ મીડિયા નો ઋણ સ્વીકારી હૃદયપૂર્વક, ભાવપૂર્વક તથા વિનમ્રતાપૂર્વક આભાર પ્રગટ કરું છું.\r\n\r\nઆપ સૌના આશીર્વાદ, સહકાર અને અનુરાગથી વૈષ્ણવ સાધુ સમાજ સતત સંગઠિત, સંસ્કારમય અને સેવાભાવથી યુક્ત બની પ્રગતિપથ પર અવિરત આગળ વધતો રહે — એવી અંતઃકરણપૂર્વકની પ્રાર્થના સાથે આ આભાર દર્શન પૂર્ણ કરું છું.\r\nઆભાર દર્શન', '1768932354_2903_1001264078.jpg', '2026-01-20 23:35:54'),
(32, 'સમાજ સેવા તથા સંસ્કાર નો દિવ્ય સમન્વય પાવન પ્રસંગો ની ઉપવિદ્વાદિક ', 'તા. ૧૮-૦૧-૨૦૨૬ના પાવન દિવસે સુરત મુકામે શ્રી સૌરાષ્ટ્ર વૈષ્ણવ સાધુ સમાજ, સુરતના આશીર્વાદ અને રામવાડી યુવા એકતા મંચના સુસંગઠિત આયોજન હેઠળ બે દીકરીઓના ભવ્ય, દિવ્ય અને આદર્શ સમૂહ લગ્ન પ્રસંગનું સફળતાપૂર્વક આયોજન કરવામાં આવ્યું હતું. આ પુણ્યપ્રસંગે સમાજહિતની ભાવનાથી પ્રેરિત અઢારે વર્ણના દાતાશ્રીઓએ ઉદાર હૃદયથી જે અમૂલ્ય સહયોગ અર્પણ કર્યો, તે બદલ શ્રી સૌરાષ્ટ્ર વૈષ્ણવ સાધુ સમાજ, સુરત તમામ દાતાશ્રીઓ પ્રત્યે હૃદયપૂર્વક કૃતજ્ઞતા વ્યક્ત કરે છે.\r\n\r\nઆ સમૂહ લગ્નની શરૂઆત વૈદિક પરંપરા અનુસાર મંત્રોચ્ચાર સાથે કરવામાં આવી હતી. ઋષિપુત્રો દ્વારા સંધ્યા સમયે મહા આરતી, મંત્રોચ્ચાર તથા વર-કન્યાની વરમાળા વિધિ સંપન્ન થતાં સમગ્ર પરિસર ભક્તિ, આનંદ અને આધ્યાત્મિક ઉલ્લાસથી પરિપૂર્ણ બની ગયો હતો. ત્યારબાદ સમયની માંગને અનુરૂપ સુવ્યવસ્થિત લગ્ન ઇવેન્ટ કાર્યક્રમ યોજાયો, જેમાં ઉપસ્થિત સર્વે મહેમાનો આનંદવિભોર થયા હતા.\r\n\r\nઆ ભવ્ય સમારોહમાં વૈષ્ણવ સાધુ સમાજના સંતો, વડીલો, રામવાડી યુવા એકતા મંચના કાર્યકરો તેમજ રાજકોટ, અમદાવાદ, ભાવનગર, શિહોર, શીખલી, અમરેલી, નાથુરામ બાપુની જગ્યા, મુંબઈ (વસઈ), બારડોલી અને નવસારી સહિત વિવિધ સ્થળોથી પધારેલા માનનીય મહેમાનોની વિશાળ ઉપસ્થિતિ રહી હતી.\r\n\r\nદીપ પ્રાગટ્યના પાવન અવસરે રામમઢી, સુરતના પૂજ્ય શ્રી ગૌતમ બાપુ, હરિગુરુ આશ્રમ, સુરતના પૂજ્ય અંશુમાન બાપુ, શ્રી લાલ હનુમાનજી ધામ, કામરેજ, શ્રી હસમુખ હનુમાનજી મહારાજ (કતારગામ), શ્રી વિશ્વેશ્વર મહાદેવ મંદિર (વરાછા), શ્રી જાગૃત હનુમાનજી મહારાજ (વરાછા), શ્રી પાલડી રામજી મંદિરના મહંતો તથા ગાદીપતિઓ, કથાકાર શ્રી ત્રિકમદાસ બાપુ હરિયાણી અને શ્રી ચતુરદાસ બાપુ હરિયાણી (મુંબઈ)ની વિશેષ ઉપસ્થિતિ રહી હતી. આ સાથે વૈષ્ણવ સાધુ સમાજના પ્રમુખ શ્રી જાનકીદાસ બાપુ ગોંડલીયા, ઉપપ્રમુખ શ્રી મુકેશ બાપુ દાણીધારીયા, મંત્રી શ્રી દલપત બાપુ દાણીધારીયા, ખજાનચી શ્રી બદરીપ્રસાદ બાપુ દેસાણી, યુવા અગ્રણી શ્રી મનીષભાઈ ગોંડલીયા તથા શ્રી શાંતિરામ બાપુ કાપડી સહિત સમાજના વડીલો, દાતાશ્રીઓ અને આમંત્રિત મહેમાનોના વરદ હસ્તે દીપ પ્રાગટ્ય કરવામાં આવ્યું હતું.\r\n\r\nસમારોહ દરમિયાન પધારેલા સંતો, દાતાશ્રીઓ, સમાજના અગ્રણીઓ તથા મહેમાનોનું રામવાડી યુવા એકતા મંચની ટીમ દ્વારા આત્મીય અને ઉષ્માભર્યું સ્વાગત-અભિવાદન કરવામાં આવ્યું હતું. કુલ ૨૩૦ ટ્રોફી અને મોમેન્ટો દ્વારા કરવામાં આવેલું સન્માન સમાજ માટે ગૌરવપૂર્ણ ક્ષણ બની રહ્યું. વરપક્ષ અને કન્યાપક્ષના મહેમાનોનું ફૂલહાર, ઢોલ-નગારા અને શરણાઈ સાથે ભવ્ય સ્વાગત કરવામાં આવ્યું, જેમાં વર-કન્યાની પ્રવેશવિધિ સ્મરણિય ક્ષણરૂપ સાબિત થઈ હતી.\r\n\r\nલગ્ન પ્રસંગે પ્રેમભાવથી તૈયાર કરાયેલો રજવાડી જમણવાર,મીઠાઈ, બરફી, ઊંધિયું, પુરી, વિવિધ શાકભાજી, સલાડ, પાપડ, દાળ-ભાત અને છાસ,રામવાડી યુવા એકતા મંચની ટીમ તથા મહિલા મંડળ દ્વારા શ્રદ્ધા અને સ્નેહપૂર્વક પીરસવામાં આવ્યો હતો. સ્ટેજ સંચાલન તથા એન્કરિંગનું આયોજન રામવાડી યુવા એકતા મંચના યુવા અગ્રણી શ્રી મનીષભાઈ ગોંડલીયા, શ્રી જાનકીદાસ બાપુ ગોંડલીયા તથા શ્રી હિમેનભાઈ ગોંડલીયા દ્વારા સુવ્યવસ્થિત રીતે કરવામાં આવ્યું હતું.\r\n\r\nઆ સમૂહ લગ્ન દરમિયાન લગ્ન ગીતોની સુંદર વ્યવસ્થા કરવામાં આવી હતી, જેમાં વૈષ્ણવ સાધુ સમાજના યુવા દીકરા-દીકરીઓએ ઉત્સાહપૂર્વક ભાગ લીધો હતો. વિશેષ આનંદની વાત એ રહી કે જ્યારે શ્રી મનીષભાઈ ગોંડલીયા દ્વારા સ્ટેજ પરથી આગામી વર્ષના દ્વિતીય સમૂહ લગ્નની જાહેરાત કરવામાં આવી, ત્યારે દાતાશ્રીઓ તરફથી તરત જ એડવાન્સ દાનની ઉદાર શરૂઆત જોવા મળી હતી.\r\n\r\nરામવાડી યુવા એકતા મંચના યુવા અગ્રણી શ્રી મનીષભાઈ ગોંડલીયા તથા સમગ્ર ટીમ દ્વારા કરવામાં આવેલું આયોજન અને સંચાલન પ્રશંસનીય અને અનુસરણયોગ્ય રહ્યું. વરપક્ષ કે કન્યાપક્ષ પાસેથી ફી રૂપે એક પણ રૂપિયો લીધા વિના, ૨૩૦ કરિયાવરની વસ્તુઓ સાથે દીકરીઓ માટે બ્યુટી પાર્લર સહિતની સંપૂર્ણ વ્યવસ્થા ઉભી કરી આ સમૂહ લગ્ન સમારોહને અભૂતપૂર્વ સફળતા પ્રાપ્ત થઈ. આ આયોજન માત્ર સુરત માટે નહીં, પરંતુ સમગ્ર ગુજરાત માટે આદર્શ સમૂહ લગ્નનું ઉત્તમ ઉદાહરણ બની રહ્યું છે.\r\n\r\nસમારોહ દરમિયાન પધારેલા સંતો, મહંતો, દાતાશ્રીઓ, મહેમાનો તથા વડીલોના આદર-સત્કારમાં જો કોઈ ક્ષતિ રહી ગઈ હોય તો શ્રી સૌરાષ્ટ્ર વૈષ્ણવ સાધુ સમાજ, સુરત તથા રામવાડી યુવા એકતા મંચ હૃદયપૂર્વક ક્ષમાયાચના કરે છે. તન-મન-ધનથી સહયોગ આપનાર તમામ દાતાશ્રીઓ તથા પધારેલા આમંત્રિત મહેમાનોનો ફરી એકવાર હૃદયપૂર્વક આભાર વ્યક્ત કરવામાં આવે છે.', '1768994225_7310_1001265750.jpg,1768994225_2228_1001265753.jpg,1768994225_9091_1001265756.jpg,1768994225_7491_1001265759.jpg,1768994225_6012_1001265762.jpg,1768994225_1765_1001265777.jpg,1768994225_2914_1001265765.jpg,1768994225_4793_1001265771.jpg,1768994225_6925_1001265747.jpg,1768994225_8317_1001265768.jpg,1768994225_7584_1001265744.jpg', '2026-01-21 00:00:00'),
(33, 'પાણી સંરક્ષણના સંસ્કારને વૈચારિક દિશા આપતી એક યુવા સંશોધિકા  વેદિકા સંતદાસ હરિયાણી', 'પર્યાવરણ સંરક્ષણ અને સમાજહિતના સંશોધન ક્ષેત્રે ગુજરાતની ધરતી પર એક આશાસ્પદ નામ તરીકે વેદિકા સંતદાસ હરિયાણીનો ઉલ્લેખ આદરપૂર્વક થાય છે. મહુવા તાલુકાના તલગાજરડા ગામે જન્મેલ વેદિકાબેનનું જીવન સંસ્કાર, સાધના અને સેવા સાથે જોડાયેલું રહ્યું છે.\r\n\r\nતેમના પિતા શ્રી સંતદાસ હરિયાણી પૂજ્ય મોરારી બાપુની સેવામા સદાય સમર્પિત છે, જ્યારે માતા શ્રીમતી કાંતાબેન હરિયાણી પરિવારના સંસ્કાર અને સંયમનું પ્રતીક છે. આ આધ્યાત્મિક અને સાંસ્કૃતિક વાતાવરણમાં ઉછરેલી વેદિકાબેને પ્રાથમિક શિક્ષણ મહુવામાં પૂર્ણ કર્યા બાદ ભાવનગર અને અમદાવાદમાં ઉચ્ચ અભ્યાસ દ્વારા પોતાની વૈચારિક ક્ષિતિજ વિસ્તારી.\r\n\r\nવર્ષ ૨૦૧૮માં તેમણે UGC NET તથા GSET જેવી રાષ્ટ્રીય સ્તરની પરીક્ષાઓ સફળતાપૂર્વક પાસ કરી પોતાની શૈક્ષણિક પ્રતિભાનો પરિચય આપ્યો. ત્યારબાદ પોતાની બહેન ચિ.ડો. વૈદહી સી. હરિયાણીની પ્રેરણાથી તેમણે સંશોધનક્ષેત્રે પ્રવેશ કર્યો અને.પીએચ.ડી.ની યાત્રા શરૂ કરી. વેદિકાબેન પોતાની દરેક સફળતાનું શ્રેય પૂજ્ય બાપુની કૃપાને અર્પણ કરે છે.આ ભાવ તેમનાં વ્યક્તિત્વની વિનમ્રતા અને શ્રદ્ધાને ઉજાગર કરે છે.\r\n\r\nપાણી સંકટ જેવી વૈશ્વિક સમસ્યાને કેન્દ્રમાં રાખીને સંશોધન કરવાનો વિચાર તેમને તેમના માર્ગદર્શક પ્રો. ડો. જે.એમ. બદિયાની (ડિપાર્ટમેન્ટ ઓફ બિઝનેસ એડમિનિસ્ટ્રેશન, એમ.કે.બી.યુ.)ની માર્ગદર્શનસભર સલાહથી પ્રાપ્ત થયો. ભવિષ્યની પેઢી માટે ઉપયોગી સાબિત થાય એવા વિષય પર સંશોધન કરવાની દૃષ્ટિથી તેમણે વોટર મેનેજમેન્ટ (પાણી વ્યવસ્થાપન) જેવા અત્યંત મહત્વના વિષયને પસંદ કર્યો.\r\n\r\nતેમની થીસીસનું શીર્ષક “ઘરગથ્થુ પાણી વ્યવસ્થાપન પરની ધારણાઓ” છે. આ સંશોધનમાં લોકોના દૈનિક પાણી ઉપયોગ, તેમની માનસિકતા અને પાણી વ્યવસ્થાપન પ્રત્યેના અભિગમનો વિશ્લેષણાત્મક અભ્યાસ કરવામાં આવ્યો છે. વેદિકાબેનનું સંશોધન આ વાતને રેખાંકિત કરે છે કે જો સમાજની ધારણાઓને યોગ્ય રીતે સમજવામાં આવે, તો પાણી સંરક્ષણના પ્રયાસોને વધુ અસરકારક બનાવી શકાય છે. આ વિચારધારા સંયુક્ત રાષ્ટ્રના SDG સસ્ટેનેબલ ડેવલપમેન્ટ ગોલ્સના લક્ષ્યો સાથે પણ સુસંગત છે.\r\n\r\nઆ રીતે, વેદિકા સંતદાસ હરિયાણી માત્ર એક સંશોધિકા નથી, પરંતુ પાણી સંરક્ષણ જેવા જીવંત મુદ્દે સમાજને જાગૃત કરનારી એક સંવેદનશીલ વિચારધારા છે. તેમના કાર્યથી આશા જગે છે કે આવનારી પેઢી માટે પાણીનું સંરક્ષણ માત્ર નીતિ નહીં, પરંતુ સંસ્કાર બની રહેશે.', '1769011882_6767_1001266342.jpg,1769011882_1327_1001266322.jpg,1769011882_2858_1001266320.jpg,1769011882_5954_1001266321.jpg,1769011882_4662_1001266316.jpg', '2026-01-21 00:00:00'),
(34, 'શ્રી વૈષ્ણવ સાધુ સમાજ (બા.વૈ.) ટ્રસ્ટ, જામનગર સમસ્ત સમાજ પરિવારનું “સ્નેહ મિલન–૨૦૨૬”', 'સમાજજીવનમાં પરસ્પર સ્નેહ, સહકાર અને એકતાનું દ્રઢ બંધન રચવાના પવિત્ર ઉદ્દેશ્ય સાથે શ્રી વૈષ્ણવ સાધુ સમાજ (બા.વૈ.) ટ્રસ્ટ, જામનગર દ્વારા વર્ષ ૨૦૨૬નું સમસ્ત સમાજ પરિવારનું સ્નેહ મિલન સમારોહ ભવ્ય અને ભાવસભર રીતે આયોજિત કરવામાં આવ્યો છે.\r\n\r\nઆ સ્નેહ મિલન સમારોહ\r\nતા. ૨૮ ફેબ્રુઆરી ૨૦૨૬, શનિવાર\r\nસાંજે ૫:૦૦ કલાકે\r\nગાંધીનગર રોડ સ્થિત ગુર્જર સુતારની વાડી, જામનગર\r\nમુકામે યોજાશે.\r\n\r\nઆ શુભ અવસર પર સમાજના સર્વે પરીવારોને આત્મીય ઉપસ્થિતિ આપીને કાર્યક્રમને ગૌરવ આપવાનો વિનમ્ર અનુરોધ કરવામાં આવે છે. સ્નેહ મિલન સમારોહ દરમિયાન સમાજની એકતા વધુ મજબૂત બને તથા સામૂહિક ચિંતન દ્વારા વિકાસના નવા માર્ગો ખુલશે તે હેતુસર સમાજની પ્રગતિ અને ભાવિ આયોજન સંબંધિત વિવિધ મહત્વપૂર્ણ મુદ્દાઓ પર વિચારવિમર્શ કરવામાં આવશે.\r\n\r\nઆયોજન પૂર્વ મિટિંગ\r\nઆ સ્નેહ મિલન સમારોહના સુવ્યવસ્થિત આયોજનના ભાગરૂપે\r\nતા. ૨૫ જાન્યુઆરી ૨૦૨૬\r\nસાંજે ૫:૦૦ કલાકે\r\nરણજીતનગર, લેઉવા પટેલ સમાજ પાસે, બ્લોક નં. A-2, રૂમ નં. ૧૬, ટ્રસ્ટ કાર્યાલય\r\nમુકામે સમાજની એક મહત્વપૂર્ણ મિટિંગનું આયોજન કરવામાં આવ્યું છે.\r\n\r\nઆ મિટિંગમાં સમાજના આગેવાનો, ટ્રસ્ટીઓ તથા કાર્યકરોની વિશેષ ઉપસ્થિતિ અપેક્ષિત છે. મિટિંગ દરમિયાન ખાસ કરીને સ્નેહ મિલન સમારોહની રૂપરેખા, કાર્યક્રમની વ્યવસ્થા તથા જવાબદારીઓના વિતરણ અંગે ચર્ચા કરવામાં આવશે.\r\n\r\nઅનુરોધક\r\nઆ સમગ્ર આયોજન માટે સમાજના આગેવાનો દ્વારા હૃદયપૂર્વક અનુરોધ કરવામાં આવે છે:\r\n\r\nઅધ્યક્ષ: શ્રી પ્રવીણભાઈ ગોંડલીયા\r\nપ્રમુખ: શ્રી દિલીપભાઈ કાપડી\r\nઉપપ્રમુખ: શ્રી પિયુષભાઈ દુધરેજીયા\r\nમહિલા પ્રમુખ: શ્રીમતી વનીતાબેન દેસાણી\r\nખજાનચી: શ્રી મહેશભાઈ કાપડી\r\nભાજપ જામનગર જિલ્લા મહિલા મહામંત્રી: શ્રીમતી મનીષાબેન દાણીધારીયા\r\nસભ્યો: શ્રી બળદેવભાઈ રવિભાણ, શ્રી વિમલભાઈ મણીરામજી દાણીધારીયા\r\n\r\nસમસ્ત સમાજ પરિવારને વિનમ્ર આમંત્રણ છે કે આ સ્નેહ, સંવાદ અને સંગઠનની યાત્રામાં સહભાગી બની સમાજને નવી દિશા અને દૃઢ શક્તિ પ્રદાન કરીએ.\r\n\r\n', '1769065244_7684_1001268368.jpg', '2026-01-22 12:30:44'),
(35, 'રાણપર તાલુકો બાબરા ખાતે સેવાસંકલ્પનું સુવર્ણ સાક્ષાત્કાર : પાંચ દીકરીઓના સમૂહ લગ્નનું દિવ્ય આયોજન', 'સમાજના સ્ત્રી સશક્તિકરણ અને નારીસન્માનના પાવન સંકલ્પને સાકાર કરતી એક અતિઉજ્જ્વલ પ્રસંગ તા. ૨૨/૦૧/૨૦૨૬ના રોજ રાણપર .તાલુકો.બાબરા, જિલ્લો અમરેલી ખાતે ભવ્યતા અને ભાવનાત્મક ઉષ્મા સાથે યોજાઈ ગયો. શ્રી ક્રિષ્ના સર્વ સેવા ટ્રસ્ટ, રાજકોટ તથા તેના કરુણામય પ્રેરણાસ્ત્રોત સારિકાબેન દેશાણીના સુદૃઢ આયોજનથી આયોજિત પાંચ દીકરીઓના પ્રથમ સમૂહ લગ્ન જાજરમાન રીતે સંપન્ન થયા.આ સમૂહ લગ્ન માત્ર વિધિ કે પરંપરાનું \r\n\r\nપાલન નહોતું, પરંતુ સમાજ માટે એક જીવંત સંદેશ હતો“દીકરી બોજ નહીં, દીકરી ગૌરવ છે.”પાંચેય કન્યાઓના વૈવાહિક જીવનમાં સુખ, સમૃદ્ધિ અને સ્વાભિમાનની પાયાની ઇંટ ગોઠવવા માટે સંસ્થાદ્વારા અઢળક કરિયાવરનું દાન કરવામાં આવ્યું. ઘરગથ્થુ સાધનો, વસ્ત્રો, અલંકારો અને જીવનની આવશ્યક ચીજવસ્તુઓ સાથે દરેક દીકરીને સન્માનભર્યું વિદાયસન્માન આપવામાં આવ્યું જે સેવા નહીં પરંતુ માતૃત્વસભર કરુણાનો પ્રતિક હતું.\r\n\r\nઆ પાવન પ્રસંગે અનેક સંતો, મહંતો, વિદ્વાનો અને સમાજના મહાનુભાવોની પાવન ઉપસ્થિતિએ સમગ્ર વાતાવરણને આધ્યાત્મિક દિવ્યતાથી અલંકૃત કરી દીધું. વેદમંત્રોચ્ચાર, આશીર્વચનો અને શુભકામનાઓના સ્વરોએ આ સમૂહ લગ્નને એક અવિસ્મરણીય અનુભવમાં રૂપાંતરિત કરી દીધા.સારિકાબેન દેશાણી દ્વારા અપાયેલો આ સેવાયજ્ઞ સમાજ માટે દીવાદાંડી સમાન છે જ્યાં \r\n\r\nદીકરીઓના ભવિષ્યને સુરક્ષા, સન્માન અને સ્વાવલંબનની દિશામાં આગળ ધપાવવાનો સંકલ્પ સ્પષ્ટ દેખાય છે. એમના પ્રયાસોએ સાબિત કર્યું કે સાચી સેવા એ જ છે, જે નિઃશબ્દ રીતે પણ જીવન બદલી શકે.આ સમૂહ લગ્ન માત્ર પાંચ પરિવારના નહીં, પરંતુ સમગ્ર સમાજના આનંદ અને ગૌરવનો ઉત્સવ બન્યા. આવા પ્રસંગો સમાજમાં માનવતા, સમરસતા અને સહકારની ભાવનાને વધુ પ્રબળ બનાવે છે અને આવતી પેઢીને સેવાના માર્ગે પ્રેરણા આપે છે.', '1769226291_3403_1001272811.jpg,1769226291_8393_1001272038.jpg,1769226291_7682_1001271957.jpg,1769226291_9646_1001271770.jpg', '2026-01-24 00:00:00'),
(36, 'સમાજસેવાની સદ્ પરંપરા : નવયુગનો પ્રારંભ', 'આપડા માર્ગી વૈષ્ણવ સાધુ સમાજ રાજકોટ કમિટી દ્વારા પોલીસ વિભાગની શારીરિક કસોટી માટે રાજકોટ ખાતે આવનાર સમાજના વિદ્યાર્થીઓ માટે રહેણાંક તથા ભોજનની નિઃશુલ્ક વ્યવસ્થા કરવાની સેવાભાવી જાહેરાત કરવામાં આવી હતી. આ જાહેરાતને સમાજ તરફથી મળેલ ઉત્તમ પ્રતિસાદ સમાજની એકતા, સંવેદનશીલતા અને કર્તવ્યબોધનો જીવંત પરિચય કરાવે છે.\r\n\r\nઆ સેવાયોજનાના અનુસંધાનમાં આજ રોજ આપડા સમાજનું ગૌરવ સમાન એવી કુ. દીપાલીબેન ઘનશ્યામભાઈ દુધરેજીયા તથા કુ. દક્ષાબેન સીતારામભાઈ દાણીધારીયા ભાવનગરથી એમના પૂજ્ય પિતાશ્રી સાથે રાજકોટ મુકામે આવેલ સીતારામ છાત્રાલય ખાતે પધાર્યા હતા. સંસ્થા દ્વારા બંને દીકરીઓ માટે રાત્રિભોજન, સવારનો નાસ્તો તેમજ શારીરિક કસોટી માટે મવડી પોલીસ હેડક્વાર્ટર સુધી પહોંચાડવાની સંપૂર્ણ વ્યવસ્થા કરવામાં આવી છે.\r\n\r\nઆ બાબત અંગે સંસ્થાની યાદીમાં શ્રી ચેતનભાઈ ગોંડલીયા તથા શ્રી ઉજેશભાઈ દેશાણી દ્વારા જણાવવામાં આવ્યું છે કે સમાજના દરેક સંતાનને પરીક્ષાના આ મહત્વના તબક્કે કોઈ અસુવિધા ન પડે એ જ આ સેવાકાર્યનો મુખ્ય હેતુ છે.\r\n\r\nવિશેષ ગૌરવની વાત એ છે કે સીતારામ છાત્રાલય ખાતે પહોંચ્યા બાદ બંને દીકરીઓને ત્યાં પોતાના ઘર જેવો આત્મીય અને સંસ્કારસભર માહોલ પ્રાપ્ત થયો. તેઓએ સ્વેચ્છાએ ગૃહમાતા સાથે રસોઈ કાર્યમાં સહભાગી બની, પરિવારભાવના સાથે જોડાઈ સમરસતા, સહકાર અને સંસ્કૃતિના ઉત્તમ સંસ્કારનું ઉદાહરણ સમાજ સમક્ષ પ્રસ્તુત કર્યું.\r\n\r\nઆ ઘટના માત્ર વ્યવસ્થાનું વર્ણન નથી, પરંતુ સમાજના સંસ્કાર, એકતા અને સેવાભાવના મૂલ્યોનું પ્રતિબિંબ છે. નિઃસ્વાર્થ સેવા, પરસ્પર વિશ્વાસ અને પરિવારભાવના  આ ત્રિવેણીના સંગમથી આજથી એક નવયુગની શુભ શરૂઆત થઈ રહી છે, એવું નિઃસંકોચ કહી શકાય.\r\n\r\nજય શ્રી રામ \r\nસમાજની સેવા, સંસ્કાર અને એકતા સદાય અવિરત રહે  એ જ શુભેચ્છા.', '1769272311_1915_1001274031.jpg,1769272311_5363_1001274357.jpg', '2026-01-24 22:01:51');
